# END GENERATED V85R BUNDLE

# V85 NAS-local stitching. Kept in this single-file client so R2 self-updates
# carry the whole worker. There is no service, timer or external Python package.
STITCH_POLICY = "v85r"
STITCH_REVISION = "v85r-rebuilt-1"
STITCH_CORPUS_SHA = "5b2765ecb4f6483c8e48b5a6c958c7c0d8082764d4da57901626a22569c6346b"
STITCH_MAX_INPUT = 2_500_000_000
STITCH_MIN_MEMORY = 384 * 1024 * 1024
STITCH_ACTIVE = threading.Event()
STITCH_STATUS = CleanupStatus()


class StitchHold(RuntimeError):
    pass


def stitch_resources(cfg, input_bytes=0):
    """Unknown resource telemetry is HOLD. Consult cgroup headroom as well."""
    import shutil
    _, memory = meminfo_bytes(_read_text("/proc/meminfo"))
    try:
        limit = Path("/sys/fs/cgroup/memory.max").read_text().strip()
        used = int(Path("/sys/fs/cgroup/memory.current").read_text())
        if limit != "max":
            memory = min(memory, int(limit) - used)
    except (OSError, ValueError):
        # cgroup v1 is bounded independently when it is present.
        try:
            limit = int(Path("/sys/fs/cgroup/memory/memory.limit_in_bytes").read_text())
            used = int(Path("/sys/fs/cgroup/memory/memory.usage_in_bytes").read_text())
            memory = min(memory, limit - used)
        except (OSError, ValueError):
            if cgroup_memory_limit():
                raise StitchHold("cgroup memory usage unavailable")
    try:
        cpus = len(os.sched_getaffinity(0))
    except AttributeError:
        cpus = os.cpu_count() or 1
    cpus = min(cpus, cgroup_cpu_limit() or cpus)
    load = os.getloadavg()[0]
    if memory < STITCH_MIN_MEMORY or load > 1.5 * max(1, cpus):
        raise StitchHold("NAS memory or load critical")
    if not os.path.ismount(str(cfg.output_dir)):
        raise StitchHold("NAS output root is not mounted")
    if shutil.disk_usage(cfg.output_dir).free < max(cfg.min_free_bytes, 1024**3) + int(input_bytes * 2.2):
        raise StitchHold("NAS free-space reserve reached")


def stitch_priority():
    import shutil
    if not sys.platform.startswith("linux") or not shutil.which("nice") or not shutil.which("ionice"):
        raise StitchHold("Linux nice/ionice required for stitch lane")
    tid = threading.get_native_id()
    os.setpriority(os.PRIO_PROCESS, tid, 19)
    subprocess.run(["ionice", "-c", "3", "-p", str(tid)], check=True,
                   stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)


class StitchStop:
    """Kill the current child on shutdown/update or critical resources."""
    def __init__(self, cfg, stop):
        self.cfg, self.stop, self.last, self.reason = cfg, stop, 0.0, ""

    def is_set(self):
        if self.stop.is_set():
            return True
        if time.monotonic() - self.last > 5:
            self.last = time.monotonic()
            try:
                stitch_resources(self.cfg)
            except Exception as exc:
                self.reason = str(exc)
        return bool(self.reason)


def stitch_run(args, deadline, stop, stdout=None):
    # The worker thread is already nice19/idle; explicitly apply the same
    # priorities to FFmpeg and ffprobe children. No '-t' silent ionice fallback.
    prefix = ["nice", "-n", "19", "ionice", "-c", "3"] if sys.platform.startswith("linux") else []
    measured = run_measured(prefix + list(args), deadline, stop, stdout_path=stdout, niced=False)
    if measured["returncode"] != 0:
        raise StitchHold("native media check failed: " + measured["stderr"][:200])
    return measured


def stitch_journal(inventory, task_id, sha, result=None, registered=False):
    with inventory.lock:
        inventory.db.execute("CREATE TABLE IF NOT EXISTS stitch_jobs(task_id INTEGER PRIMARY KEY,plan_sha TEXT NOT NULL,result TEXT,registered INTEGER NOT NULL DEFAULT 0)")
        old = inventory.db.execute("SELECT plan_sha,result FROM stitch_jobs WHERE task_id=?", (task_id,)).fetchone()
        if old and old[0] != sha:
            raise StitchHold("immutable local task identity changed")
        if result is not None:
            inventory.db.execute("INSERT INTO stitch_jobs VALUES(?,?,?,?) ON CONFLICT(task_id) DO UPDATE SET result=excluded.result,registered=excluded.registered",
                                 (task_id, sha, cleanup_json_bytes(result).decode(), int(registered)))
            inventory.db.commit()
        return json.loads(old[1]) if old and old[1] else None


def stitch_corpus(cfg, inventory):
    """Stream the exact frozen JSONL into SQLite once; never trust a row alone."""
    with inventory.lock:
        inventory.db.execute("CREATE TABLE IF NOT EXISTS v85r_stitch_corpus_meta(sha TEXT PRIMARY KEY)")
        inventory.db.execute("CREATE TABLE IF NOT EXISTS v85r_stitch_edges(a TEXT,b TEXT,nomination INTEGER,witness TEXT,PRIMARY KEY(a,b))")
        inventory.db.commit()
        if inventory.db.execute("SELECT 1 FROM v85r_stitch_corpus_meta WHERE sha=?", (STITCH_CORPUS_SHA,)).fetchone():
            return
    req = urllib.request.Request(cfg.api_base + "/account/connections/stitch/corpus")
    req.add_header("Authorization", "Bearer " + cfg.api_key)
    digest, count, nominees, size = hashlib.sha256(), 0, 0, 0
    # Import in a separate DB connection/transaction. Inventory heartbeats keep
    # reading their last completed snapshot; no partial corpus becomes usable.
    database = sqlite3.connect(str(cfg.inventory_file), timeout=60)
    try:
        database.execute("BEGIN IMMEDIATE")
        database.execute("DELETE FROM v85r_stitch_edges")
        with urllib.request.urlopen(req, timeout=HTTP_TIMEOUT_SEC) as response:
            while True:
                line = response.readline(1024 * 1024 + 1)
                if not line:
                    break
                size += len(line)
                if size > 64 * 1024 * 1024 or len(line) > 1024 * 1024:
                    raise StitchHold("frozen corpus exceeds bound")
                digest.update(line)
                row = json.loads(line)
                keys = row["source_key"]
                diagnostic = row.get("frozen_diagnostic_sha256") or ""
                if (len(keys) != 2 or (diagnostic and not re.fullmatch("[a-f0-9]{64}", diagnostic))
                        or (row.get("nomination") is True and not diagnostic)
                        or type(row.get("nomination")) is not bool or not row.get("status")):
                    raise StitchHold("frozen decision incomplete")
                database.execute("INSERT INTO v85r_stitch_edges VALUES(?,?,?,?)",
                                 (json.dumps(keys[0], separators=(",", ":")), json.dumps(keys[1], separators=(",", ":")), int(row["nomination"]), json.dumps(row, separators=(",", ":"))))
                count += 1
                nominees += int(row["nomination"])
        if digest.hexdigest() != STITCH_CORPUS_SHA or count != 73843 or nominees != 52462:
            raise StitchHold("frozen corpus hash/census differs")
        database.execute("INSERT INTO v85r_stitch_corpus_meta VALUES(?)", (STITCH_CORPUS_SHA,))
        database.commit()
    finally:
        database.close()


def stitch_source_key(c):
    return json.dumps([c["source_id"], c["sha256"], c["size_bytes"]], separators=(",", ":"))


def stitch_frozen(inventory, previous, clip):
    with inventory.lock:
        row = inventory.db.execute("SELECT witness FROM v85r_stitch_edges WHERE a=? AND b=?",
                                   (stitch_source_key(previous), stitch_source_key(clip))).fetchone()
    return json.loads(row[0]) if row else None


def stitch_v85r_bundle(state_dir):
    """Install only the embedded pinned members; verify each file before use."""
    import base64
    import gzip
    import io
    import tarfile
    blob = base64.b85decode(V85R_BUNDLE)
    if hashlib.sha256(blob).hexdigest() != V85R_BUNDLE_SHA:
        raise StitchHold("V85r bundle hash differs")
    root = Path(state_dir)/"tools"/("v85r-" + V85R_MANIFEST_SHA)
    root.mkdir(parents=True, exist_ok=True, mode=0o700)
    with tarfile.open(fileobj=io.BytesIO(gzip.decompress(blob)), mode="r:") as archive:
        manifest_body = archive.extractfile("manifest.json").read()
        if hashlib.sha256(manifest_body).hexdigest() != V85R_MANIFEST_SHA:
            raise StitchHold("V85r manifest hash differs")
        manifest = json.loads(manifest_body)
        pins = dict(manifest["files"], **{"manifest.json": V85R_MANIFEST_SHA})
        if manifest["policy"] != STITCH_POLICY or set(archive.getnames()) != set(pins):
            raise StitchHold("V85r bundle membership differs")
        for member in archive:
            if not member.isfile() or member.name.startswith("/") or ".." in Path(member.name).parts or member.size > 16*1024*1024:
                raise StitchHold("V85r member is unsafe")
            body = archive.extractfile(member).read()
            if hashlib.sha256(body).hexdigest() != pins[member.name]:
                raise StitchHold("V85r member hash differs")
            path = root/member.name
            if path.exists():
                if path.is_symlink() or hashlib.sha256(path.read_bytes()).hexdigest() != pins[member.name]:
                    raise StitchHold("installed V85r member hash differs")
            else:
                path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
                atomic_write(path, body)
                os.chmod(path, member.mode)
    return root


V85R_TOOL_VERSION = "N-126826-gc0e8b139fd-20260924"
V85R_TOOLS = {
    "ffmpeg": ("2388de8e05ad71c913ee1a9c4504a1aa5de09ac100a1de92858dd9ec08e9f98b", 174165384),
    "ffprobe": ("9b2bac862606a48f5bc36091d38e5334cf241538a6f4cc47c60f68e7973a365c", 173923656),
}


def stitch_v85r_tools(cfg, deadline, stop):
    import platform
    if not sys.platform.startswith("linux") or benchmark_tool_arch(platform.machine()) != "x86_64":
        raise StitchHold("V85r requires Linux x86_64")
    root = Path(cfg.state_dir)/"tools"/("v85r-ffmpeg-"+V85R_TOOL_VERSION)
    root.mkdir(parents=True, exist_ok=True, mode=0o700)
    tools = {}
    for name,(sha,size) in V85R_TOOLS.items():
        target = root/name
        if not _verified_binary(target,sha):
            capability = request_json(cfg,"GET","/account/connections/stitch/tools/"+name)
            if capability.get("sha256") != sha or capability.get("size_bytes") != size:
                raise StitchHold("V85r tool capability identity differs")
            url = capability["url"]
            CLIENT_LOG_RING.add_secrets((url,))
            if urllib.parse.urlsplit(url).scheme != "https":
                raise StitchHold("V85r tool download requires HTTPS")
            temporary = root/(name+".partial")
            try:
                digest,total=hashlib.sha256(),0
                req=urllib.request.Request(url,headers={"If-Match":capability["if_match"]})
                with urllib.request.urlopen(req,timeout=min(60,max(.1,deadline-time.monotonic()))) as response, temporary.open("wb") as output:
                    remember_response_secrets(response)
                    while True:
                        _check_benchmark_tool_budget(deadline,stop)
                        block=response.read(1024*1024)
                        if not block:break
                        total+=len(block)
                        if total>size:raise StitchHold("V85r tool exceeds pinned size")
                        output.write(block);digest.update(block)
                    output.flush();os.fsync(output.fileno())
                if total!=size or digest.hexdigest()!=sha:
                    raise StitchHold("V85r tool hash differs")
                os.chmod(temporary,0o700)
                os.replace(temporary,target);fsync_dir(root)
            except Exception:
                # Transport exceptions may contain a signed capability. Log only
                # this stable error; preserve existing installed verified tools.
                raise StitchHold("V85r pinned tool download failed") from None
            finally:
                try:temporary.unlink()
                except FileNotFoundError:pass
        tools[name]=str(target)
    return tools


def stitch_v85r_provenance(tools):
    for name,(sha,size) in V85R_TOOLS.items():
        if not _verified_binary(Path(tools[name]),sha) or Path(tools[name]).stat().st_size!=size:
            raise StitchHold("V85r requires the pinned October " + name)
    return dict(policy=STITCH_POLICY, manifest_sha256=V85R_MANIFEST_SHA,
                ffmpeg_version=V85R_TOOL_VERSION, ffprobe_version=V85R_TOOL_VERSION,
                ffmpeg_sha256=V85R_TOOLS["ffmpeg"][0], ffprobe_sha256=V85R_TOOLS["ffprobe"][0],
                october_ffmpeg_recovered=True)


def stitch_v85r_measure(cfg, inventory, previous, clip, tools, work, deadline, stop, root):
    def source(c):
        path, _, _ = hash_certification_file(cfg.output_dir, c["relative_path"], c["size_bytes"], c["sha256"])
        binding = c.get("feature_input")
        if (not binding or binding.get("clip_id") != c["source_id"] or binding.get("sha256") != c["sha256"]
                or binding.get("size_bytes") != c["size_bytes"] or binding.get("nominal_seconds",0) <= 0
                or binding.get("recording_id") != c["recording_id"]
                or parse_certification_timestamp(binding.get("start_utc"),"feature start") != parse_certification_timestamp(c["start_at"],"clip start")
                or parse_certification_timestamp(binding.get("end_utc"),"feature end") != parse_certification_timestamp(c["end_at"],"clip end")):
            raise StitchHold("V85r metadata missing or differs")
        return str(path), binding
    ap, a = source(previous)
    bp, b = source(clip)
    request = dict(prev=a, next=b, prev_path=ap, next_path=bp, tools=tools,
                   actual_span=False, frozen=stitch_frozen(inventory, previous, clip))
    (work/"v85r-request.json").write_bytes(cleanup_json_bytes(request))
    stitch_run([sys.executable, "-I", "-B", str(root/"runner.py"), str(work/"v85r-request.json")],
               min(deadline,time.monotonic()+390), stop, work/"v85r-decision.json")
    return json.loads((work/"v85r-decision.json").read_text())


class StitchDirectory:
    """Pin every directory with O_NOFOLLOW for the lifetime of a job.

    Child I/O uses /proc/self/fd paths with inherited directory descriptors on
    Linux, so renaming an ancestor cannot redirect FFmpeg outside the NAS root.
    The portable path used by disposable Mac fixtures is never used on the NAS.
    """
    def __init__(self, root, relative):
        if (not relative or relative.startswith(("/", "#", "@")) or "\\" in relative
                or any(p in ("", ".", "..") for p in relative.split("/"))):
            raise StitchHold("invalid stitch directory")
        self.root, self.relative, self.fds = Path(root), relative, []

    def __enter__(self):
        try:
            fd = os.open(str(self.root), os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
            self.fds.append(fd)
            device = os.fstat(fd).st_dev
            for part in self.relative.split("/"):
                try:
                    os.mkdir(part, 0o700, dir_fd=self.fds[-1])
                    os.fsync(self.fds[-1])
                except FileExistsError:
                    pass
                fd = os.open(part, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=self.fds[-1])
                self.fds.append(fd)
                if os.fstat(fd).st_dev != device:
                    raise StitchHold("nested stitch filesystem refused")
            return self
        except BaseException:
            self.__exit__(None, None, None)
            raise

    @property
    def path(self):
        if sys.platform.startswith("linux"):
            return Path("/proc/%d/fd/%d" % (os.getpid(), self.fds[-1]))
        return self.root / self.relative

    def __exit__(self, *unused):
        for fd in reversed(self.fds):
            os.close(fd)
        self.fds.clear()

    def publish(self, temporary, name):
        fd = os.open(temporary, os.O_RDONLY | os.O_NOFOLLOW, dir_fd=self.fds[-1])
        try:
            os.fsync(fd)
        finally:
            os.close(fd)
        # link+unlink is an atomic create-only publication, unlike rename which
        # overwrites. A restart may adopt only byte-identical existing output.
        try:
            os.link(temporary, name, src_dir_fd=self.fds[-1], dst_dir_fd=self.fds[-1], follow_symlinks=False)
        except FileExistsError:
            a, b = self.path / temporary, self.path / name
            _, st = confined_regular_file(self.root, self.relative + "/" + name)
            if (st.st_nlink != 1 and not (st.st_nlink == 2 and os.path.samestat(a.stat(), st))) or sha256_file(a) != sha256_file(b):
                raise StitchHold("published output collision")
        os.unlink(temporary, dir_fd=self.fds[-1])
        os.fsync(self.fds[-1])
        return self.path / name


def stitch_packet_rows(file):
    with open(file, encoding="ascii") as source:
        for line in source:
            line = line.strip()
            if not line:
                continue
            fields = dict(part.split("=", 1) for part in line.split("|") if "=" in part)
            if (set(fields) != {"pts", "dts", "duration", "size", "flags", "data_hash"}
                    or not fields["data_hash"].startswith("SHA256:") or len(fields["data_hash"]) != 71):
                raise StitchHold("unsupported packet mapping/side data")
            try:
                yield (int(fields["pts"]), int(fields["dts"]), int(fields["duration"]),
                       int(fields["size"]), fields["flags"], fields["data_hash"])
            except ValueError as exc:
                raise StitchHold("packet timestamps missing") from exc


def stitch_packets(ffprobe, source, target, deadline, stop, hidden=False):
    stitch_run([ffprobe, "-v", "error"] + (["-ignore_editlist", "1"] if hidden else []) +
               ["-select_streams", "v:0", "-show_packets", "-show_data_hash", "sha256",
                "-show_entries", "packet=pts,dts,duration,size,flags,data_hash:packet_side_data=side_data_type",
                "-of", "compact=p=0", str(source)], deadline, stop, target)


def stitch_frames(ffmpeg, source, target, deadline, stop):
    stitch_run([ffmpeg, "-nostdin", "-v", "error", "-xerror", "-err_detect", "explode",
                "-threads", "1", "-filter_threads", "1", "-i", str(source), "-map", "0:v:0",
                "-fps_mode", "passthrough", "-enc_time_base", "demux", "-f", "framehash", "-hash", "sha256", "-y", str(target)], deadline, stop)


def stitch_frame_rows(file):
    with open(file, encoding="ascii") as source:
        for line in source:
            if line.startswith("#") or not line.strip():
                continue
            row = [v.strip() for v in line.split(",")]
            if len(row) != 6 or len(row[5]) != 64:
                raise StitchHold("unsupported decoded frame audit")
            yield int(row[2]), row[4], row[5]


def stitch_probe(ffprobe, source, target, deadline, stop):
    stitch_run([ffprobe, "-v", "error", "-show_streams", "-show_data_hash", "sha256", "-of", "json", str(source)], deadline, stop, target)
    if target.stat().st_size > 1024 * 1024:
        raise StitchHold("oversized stream metadata")
    streams = json.loads(target.read_text())["streams"]
    if len(streams) != 1 or streams[0].get("codec_type") != "video" or streams[0].get("codec_name") != "h264":
        raise StitchHold("only positively audio-absent native H264 is admitted")
    s = streams[0]
    signature = tuple(s.get(k) for k in ("codec_name", "codec_tag_string", "width", "height", "pix_fmt", "time_base", "extradata_hash"))
    if any(v is None for v in signature) or Fraction(s["time_base"]).numerator != 1:
        raise StitchHold("unsupported codec/extradata/timebase")
    return signature


def stitch_audit_source(ffmpeg, ffprobe, source, work, index, deadline, stop):
    prefix = work / ("source-%03d" % index)
    signature = stitch_probe(ffprobe, source, prefix.with_suffix(".json"), deadline, stop)
    packets, hidden, frames = (prefix.with_suffix(suffix) for suffix in (".packets", ".hidden", ".frames"))
    stitch_packets(ffprobe, source, packets, deadline, stop)
    stitch_packets(ffprobe, source, hidden, deadline, stop, hidden=True)
    if sha256_file(packets) != sha256_file(hidden):
        raise StitchHold("hidden edit-list inventory differs")
    stitch_frames(ffmpeg, source, frames, deadline, stop)
    chain, count, last, minimum, maximum = hashlib.sha256(), 0, None, None, 0
    for pts, dts, duration, size, flags, payload in stitch_packet_rows(packets):
        if duration <= 0 or (last is not None and dts <= last) or (count == 0 and "K" not in flags):
            raise StitchHold("source native packet interval invalid")
        chain.update(("%s:%s\n" % (size, payload)).encode())
        minimum = pts if minimum is None else min(minimum, pts)
        maximum = max(maximum, pts + duration)
        count += 1
        last = dts
    decoded, last = 0, None
    for pts, size, digest in stitch_frame_rows(frames):
        if last is not None and pts <= last:
            raise StitchHold("source presentation PTS not increasing")
        last, decoded = pts, decoded + 1
    if count == 0 or count != decoded or minimum != 0:
        raise StitchHold("source EOF/packet/frame assumption failed")
    return dict(signature=signature, packets=packets, frames=frames, count=count,
                chain=chain.hexdigest(), span=maximum * Fraction(signature[5]))


def stitch_audit_output(ffmpeg, ffprobe, output, sources, work, deadline, stop):
    signature = stitch_probe(ffprobe, output, work / "output.json", deadline, stop)
    if any(s["signature"] != signature for s in sources):
        raise StitchHold("output codec/extradata/timebase changed")
    packets, hidden, frames = (work / name for name in ("output.packets", "output.hidden", "output.frames"))
    stitch_packets(ffprobe, output, packets, deadline, stop)
    stitch_packets(ffprobe, output, hidden, deadline, stop, hidden=True)
    if sha256_file(packets) != sha256_file(hidden):
        raise StitchHold("output hidden payload inventory differs")
    stitch_frames(ffmpeg, output, frames, deadline, stop)
    actual, decoded, last_dts = iter(stitch_packet_rows(packets)), iter(stitch_frame_rows(frames)), None
    offset = Fraction(0)
    for source in sources:
        translation = None
        for expected in stitch_packet_rows(source["packets"]):
            row = next(actual, None)
            if row is None or row[2:] != expected[2:]:
                raise StitchHold("source packet omitted, changed or reordered")
            dp, dd = row[0] - expected[0], row[1] - expected[1]
            if dp != dd or (translation is not None and dp != translation) or (last_dts is not None and row[1] <= last_dts):
                raise StitchHold("non-affine PTS/DTS translation or DTS regression")
            if abs(dp * Fraction(signature[5]) - offset) > Fraction(signature[5]):
                raise StitchHold("native span changed or gap compressed")
            translation, last_dts = dp, row[1]
        for expected in stitch_frame_rows(source["frames"]):
            row = next(decoded, None)
            if row is None or row[1:] != expected[1:] or row[0]-expected[0] != translation:
                raise StitchHold("decoded EOF/pixel/raw PTS inventory differs")
        offset += source["span"]
    if next(actual, None) is not None or next(decoded, None) is not None:
        raise StitchHold("extra output packets or frames")
    # Full strict EOF decode above includes every frame. Decode each seam again
    # with an independent seek to exercise keyframe/preroll behavior.
    offset = Fraction(0)
    for source in sources[:-1]:
        offset += source["span"]
        stitch_run([ffmpeg, "-nostdin", "-v", "error", "-xerror", "-err_detect", "explode", "-threads", "1",
                    "-ss", "%.6f" % max(0, float(offset) - 2), "-i", str(output), "-t", "4", "-map", "0:v:0", "-f", "null", "-"], deadline, stop)


# mdat/Annex B and SPS/VUI parser ported from the existing repair owner,
# ~/stoarama-repair/bin/repair.py SHA256
# 0f662c6897002a0760e085477a31c2c07f9ce0c320ec3ce9e06e816f5a876e85.
# Parser semantics are unchanged; this caller only admits bounded files with
# genuine VUI fps. No inferred/default FPS or repaired continuity is admitted.
class StitchRepairBits:
    def __init__(s, b): s.b, s.p = b, 0
    def u(s, n):
        v = 0
        for _ in range(n):
            if s.p >= len(s.b) * 8: raise ValueError('eof')
            v = (v << 1) | ((s.b[s.p >> 3] >> (7 - (s.p & 7))) & 1); s.p += 1
        return v
    def ue(s):
        z = 0
        while s.u(1) == 0:
            z += 1
            if z > 32: raise ValueError('ue')
        return (1 << z) - 1 + (s.u(z) if z else 0)
    def se(s):
        k = s.ue(); return (k + 1) // 2 if k & 1 else -(k // 2)
def stitch_repair_fps(nal):
    b = bytes(nal[1:]); b = re.sub(rb'\x00\x00\x03', b'\x00\x00', b)
    r = StitchRepairBits(b); prof = r.u(8); r.u(16); r.ue()
    if prof in (100, 110, 122, 244, 44, 83, 86, 118, 128, 138, 139, 134, 135):
        cf = r.ue()
        if cf == 3: r.u(1)
        r.ue(); r.ue(); r.u(1)
        if r.u(1):
            for i in range(8 if cf != 3 else 12):
                if r.u(1):
                    last = nxt = 8
                    for _ in range(16 if i < 6 else 64):
                        if nxt: nxt = (last + r.se()) % 256
                        last = last if nxt == 0 else nxt
    r.ue(); pt = r.ue()
    if pt == 0: r.ue()
    elif pt == 1:
        r.u(1); r.se(); r.se()
        for _ in range(r.ue()): r.se()
    r.ue(); r.u(1); r.ue(); r.ue()
    if not r.u(1): r.u(1)
    r.u(1)
    if r.u(1): [r.ue() for _ in range(4)]
    if not r.u(1): return None
    if r.u(1):
        if r.u(8) == 255: r.u(32)
    if r.u(1): r.u(1)
    if r.u(1):
        r.u(4)
        if r.u(1): r.u(24)
    if r.u(1): r.ue(); r.ue()
    if not r.u(1): return None
    nu, ts = r.u(32), r.u(32)
    if nu == 0 or ts == 0: return None
    return Fraction(ts, 2 * nu)

# ---------- mdat -> annexb ----------
def stitch_repair_signature(head):
    return len(head) >= 48 and head[44:48] == b'mdat' and struct.unpack('>I', head[40:44])[0] == 0 and head[4:8] == b'ftyp' and b'moov' not in head[:48]
STITCH_REPAIR_AUD_RE = re.compile(rb'\x00\x00\x00\x02\x09[\x10\x30\x50\x70\x90\xb0\xd0\xf0]')
def stitch_repair_mdat(data):
    """Walk length-prefixed NALs; where junk (interleaved audio / zero holes) appears, resync on the next AUD. Returns (nals, stopmsg, gaps, gap_idx)"""
    off = 0
    while off + 8 <= len(data):
        sz, typ = struct.unpack('>I4s', data[off:off+8])
        if typ == b'mdat': off += 16 if sz == 1 else 8; break
        off += sz
    nals = []; stopmsg = 'eof'; gaps = 0; gap_idx = []
    while off + 4 <= len(data):
        ln = struct.unpack('>I', data[off:off+4])[0]
        ok = 0 < ln <= 8_000_000 and off + 4 + ln <= len(data) and not (data[off+4] & 0x80) and (data[off+4] & 0x1f) in (1, 2, 3, 4, 5, 6, 7, 8, 9)
        if not ok:
            m = STITCH_REPAIR_AUD_RE.search(data, off + 1)
            if off + 4 + ln > len(data) and 0 < ln <= 8_000_000 and (data[off+4] & 0x1f) in (1, 5) and not m:
                stopmsg = 'partial'; break
            if not m: stopmsg = 'junk_tail' if off + 4 + ln <= len(data) or ln > 8_000_000 else 'partial'; break
            off = m.start(); gaps += 1; gap_idx.append(len(nals)); continue
        nals.append(data[off+4:off+4+ln]); off += 4 + ln
    return nals, stopmsg, gaps, gap_idx
def stitch_repair_annexb(nals, drop_vcl=0, upto=None):
    if upto is not None: nals = nals[:upto]
    vcl = [i for i, n in enumerate(nals) if 1 <= (n[0] & 0x1f) <= 5]
    if len(vcl) <= drop_vcl: return None
    end = vcl[-1 - drop_vcl] + 1
    return b''.join(b'\x00\x00\x00\x01' + n for n in nals[:end]), len(vcl) - drop_vcl


def stitch_repair_local(cfg, clip, source, directory, tools, deadline, stop):
    """Labeled partial recovery, always excluded from raw retirement/V85 joins."""
    if clip["size_bytes"] > 16 * 1024 * 1024:
        return None
    with open(source, "rb") as f:
        head = f.read(48)
        if not stitch_repair_signature(head):
            return None
        data = head + f.read(16 * 1024 * 1024)
    if len(data) != clip["size_bytes"]:
        raise StitchHold("repair input size changed")
    nals, stopmsg, gaps, gap_indices = stitch_repair_mdat(data)
    del data
    sps = next((n for n in nals if n[0] & 0x1f == 7), None)
    fps = stitch_repair_fps(sps) if sps else None
    if fps is None or not 5 <= fps <= 120:
        return None
    work = directory.path
    h264, temporary = work / "repair.h264", work / "repair.partial.mp4"
    choices = [(drop, None) for drop in (0, 1)] + ([(drop, gap_indices[0]) for drop in (0, 1)] if gap_indices else [])
    for drop, upto in choices:
        built = stitch_repair_annexb(nals, drop, upto)
        if built is None:
            continue
        h264.write_bytes(built[0])
        try:
            stitch_run([tools["ffmpeg"], "-nostdin", "-v", "error", "-framerate", str(fps), "-f", "h264", "-i", str(h264),
                        "-c:v", "copy", "-an", "-threads", "1", "-movflags", "+faststart", "-y", str(temporary)], deadline, stop)
            stitch_frames(tools["ffmpeg"], temporary, work / "repair.frames", deadline, stop)
        except StitchHold:
            if stop.is_set():
                raise
            continue
        count = sum(1 for _ in stitch_frame_rows(work / "repair.frames"))
        duration = Fraction(count, 1) / fps
        if not 1 <= duration <= 60:
            continue
        size, sha = sha256_file(temporary)
        name = "repaired-%d-%s.mp4" % (clip["source_id"], sha)
        directory.publish(temporary.name, name)
        relative = directory.relative + "/" + name
        hash_certification_file(cfg.output_dir, relative, size, sha)
        proof = dict(policy=STITCH_POLICY, provenance=stitch_v85r_provenance(tools), clip_id=clip["source_id"], original_sha256=clip["sha256"], original_size_bytes=clip["size_bytes"],
                     relative_path=relative, sha256=sha, size_bytes=size, method="mdat_annexb_vui_prefix_v1",
                     fps=str(fps), fps_src="vui", frames=count, duration_seconds=float(duration),
                     note="stop=%s gaps=%d dropped_vcl=%d prefix_before_gap=%s" % (stopmsg, gaps, drop, upto is not None),
                     synthesized_timestamps=True, complete_original=False, full_decode=True, fsynced=True, readback_sha256=sha)
        sidecar = work / "repair.proof.partial.json"
        sidecar.write_bytes(cleanup_json_bytes(proof))
        directory.publish(sidecar.name, name + ".repair.json")
        return proof
    return None


def stitch_output_recheck(cfg, item, execution=True):
    """Independent local deletion gate; a server boolean is never sufficient."""
    if not getattr(cfg, "stitch_enabled", False) or (execution and not getattr(cfg, "stitch_delete_enabled", False)):
        return "local stitch/deletion switch off"
    try:
        if item.get("permit_reason") != "stitched_included" or item.get("kind") != "raw":
            return "unsupported stitch deletion reason"
        path = item["stitch_output_path"]
        marker, _ = confined_regular_file(cfg.output_dir, path + ".registered.json")
        if marker.stat().st_size > 4096:
            return "oversized registration receipt"
        registration = json.loads(marker.read_text())
        if (registration.get("recorded") is not True or registration.get("task_id") != item.get("stitch_task_id")
                or registration.get("sha256") != item["stitch_output_sha256"]):
            return "server registration receipt missing"
        # The durable local proof was written only after all native verification.
        proof_path, _ = confined_regular_file(cfg.output_dir, path + ".proof.json")
        if proof_path.stat().st_size > 1024 * 1024:
            return "oversized stitch proof"
        proof = json.loads(proof_path.read_text())
        if (proof.get("policy") != STITCH_POLICY or proof.get("provenance", {}).get("manifest_sha256") != V85R_MANIFEST_SHA
                or proof.get("relative_path") != path or proof.get("sha256") != item["stitch_output_sha256"]
                or proof.get("size_bytes") != item["stitch_output_size_bytes"]
                or not all(proof.get(k) is True for k in ("full_decode", "seam_decode", "packet_chain", "native_audit", "original_sources_no_audio", "fsynced"))):
            return "durable output proof mismatch"
        included = [p for p in proof.get("inputs", []) if p.get("clip_id") == item["source_id"] and not p.get("retirement_held", True)]
        if (len(included) != 1 or included[0].get("sha256") != item["sha256"] or included[0].get("size_bytes") != item["size_bytes"]
                or included[0].get("repaired") is not False or included[0].get("frames", 0) <= 0
                or included[0].get("frames") != included[0].get("packets") or not included[0].get("packet_chain_sha256")):
            return "raw source lacks full inclusion"
        hash_certification_file(cfg.output_dir, path, item["stitch_output_size_bytes"], item["stitch_output_sha256"])
        return None
    except Exception as exc:
        return "output fresh readback failed: " + str(exc)[:200]


@NAS_MEDIA_FENCE.delivery
def stitch_build(cfg, inventory, task, stop_event, tools, admitted=None):
    """Build/verify first; this function never unlinks source media."""
    plan = task["plan"]
    if (plan.get("policy") != STITCH_POLICY or plan.get("revision") != STITCH_REVISION
            or plan.get("corpus_sha256") != STITCH_CORPUS_SHA or plan.get("keep_policy_sha256") != CLEANUP_KEEP28_POLICY_SHA256):
        raise StitchHold("unapproved V85 policy identity")
    clips, joins = plan["clips"], plan["joins"]
    if not 1 <= len(clips) <= 200 or len(joins) != len(clips) - 1 or len(plan.get("eligible", [])) != len(clips) or sum(c["size_bytes"] for c in clips) > STITCH_MAX_INPUT:
        raise StitchHold("unbounded assembly unit")
    expected = clips[0]["relative_path"].split("/")[0] + "_V85r_keep28/" + str(plan["recording_id"]) + "/"
    if (not plan["output_folder"].startswith(expected) or not re.fullmatch(r"\d{4}-\d{2}-\d{2}T\d{2}-00-00Z", plan["output_folder"][len(expected):])):
        raise StitchHold("output must be in the stream's new versioned sibling folder")
    deadline = min(time.monotonic() + 7000, time.monotonic() + (parse_certification_timestamp(task["expires_at"], "stitch lease") - datetime.datetime.now(datetime.timezone.utc)).total_seconds() - 30)
    stop = StitchStop(cfg, stop_event)
    result = dict(policy=STITCH_POLICY, lease_token=task["lease_token"], plan_sha256=task["plan_sha256"], outputs=[], repairs=[], left_out=[], seams=[], error="")
    provenance = stitch_v85r_provenance(tools)
    root = stitch_v85r_bundle(cfg.state_dir) if admitted is None else None
    ffmpeg, ffprobe = tools["ffmpeg"], tools["ffprobe"]
    # Deterministic owner directory allows an interrupted task to be rebuilt
    # and byte-identical published runs to be adopted without overwriting.
    import contextlib
    with contextlib.ExitStack() as resources:
        directory = resources.enter_context(StitchDirectory(cfg.output_dir, plan["output_folder"]))
        work = directory.path
        def clear_scratch():
            names = ["concat.txt", "run.partial.mp4", "proof.partial.json", "output.json", "output.packets", "output.hidden", "output.frames", "repair.h264", "repair.partial.mp4", "repair.frames", "repair.proof.partial.json", "v85r-request.json", "v85r-decision.json"]
            names += ["source-%03d.%s" % (n, suffix) for n in range(len(clips)) for suffix in ("json", "packets", "hidden", "frames")]
            for name in names:
                try:
                    os.unlink(name, dir_fd=directory.fds[-1])
                except FileNotFoundError:
                    pass
            os.fsync(directory.fds[-1])
        resources.callback(clear_scratch)
        held = set()
        if admitted is None:
            inputs = plan.get("feature_inputs", [])
            if len(inputs) != len(clips):
                raise StitchHold("V85r feature metadata missing")
            clips = [dict(c, feature_input=f) for c, f in zip(clips, inputs)]
        for index in range(1, len(clips)):
            a, b = clips[index-1:index+1]
            decision = dict(policy=STITCH_POLICY, decision="hold", join=False, nomination=False, status="UNKNOWN_missing_input", reason="missing_input")
            try:
                if admitted is not None:  # explicit synthetic corpus adapter in the fake-NAS harness
                    join = joins[index-1] and admitted(b,a)
                    decision = dict(policy=STITCH_POLICY, decision="join" if join else "split", join=bool(join), nomination=bool(join),
                                    status="APPROVED85_nomination_requires_runtime_native_join_checks" if join else "SPLIT_frozen_score_reject", reason="fixture")
                else:
                    decision = stitch_v85r_measure(cfg, inventory, a, b, tools, work, deadline, stop, root)
            except (StitchHold, OSError, ValueError, KeyError):
                if stop.is_set():
                    raise StitchHold("V85r measurement cancelled")
            if (decision.get("policy") != STITCH_POLICY or decision.get("decision") not in ("join","split","hold")
                    or decision.get("join") is not (decision.get("decision") == "join")
                    or (decision.get("join") and (decision.get("nomination") is not True
                        or decision.get("status") != "APPROVED85_nomination_requires_runtime_native_join_checks"))):
                decision = dict(policy=STITCH_POLICY, decision="hold", join=False, nomination=False, status="UNKNOWN_invalid_decision", reason="invalid_decision")
            if not joins[index-1] and decision.get("join"):
                decision.update(join=False, decision="hold", reason="capture_boundary_or_frozen_veto")
            if decision.get("decision") == "hold":
                held.update((a["source_id"], b["source_id"]))
            decision.update(left_id=a["source_id"], right_id=b["source_id"])
            result["seams"].append(decision)
        sources, run_clips, run_index = [], [], 0

        def flush():
            nonlocal sources, run_clips, run_index
            if not sources:
                return
            manifest, output = work / "concat.txt", work / "run.partial.mp4"
            lines, cumulative, previous = [], Fraction(0), 0
            for clip, source in zip(run_clips, sources):
                cumulative += source["span"]
                us = round(cumulative * 1000000)
                lines.extend([concat_manifest_line(clip["_path"]), "duration %d.%06d\n" % divmod(us - previous, 1000000)])
                previous = us
            manifest.write_text("ffconcat version 1.0\n" + "".join(lines))
            stitch_run([ffmpeg, "-nostdin", "-v", "error", "-xerror", "-protocol_whitelist", MEDIA_CERTIFICATION_PROTOCOLS,
                        "-f", "concat", "-auto_convert", "0", "-safe", "0", "-i", str(manifest),
                        "-map", "0:v:0", "-an", "-c:v", "copy", "-threads", "1", "-video_track_timescale",
                        str(Fraction(sources[0]["signature"][5]).denominator), "-movflags", "+faststart", "-y", str(output)], deadline, stop)
            stitch_audit_output(ffmpeg, ffprobe, output, sources, work, deadline, stop)
            size, sha = sha256_file(output)
            name = "run-%03d-%s.mp4" % (run_index, sha)
            published = directory.publish(output.name, name)
            relative = plan["output_folder"] + "/" + name
            hash_certification_file(cfg.output_dir, relative, size, sha)  # reopen after fsync
            proof = dict(policy=STITCH_POLICY, provenance=provenance, relative_path=relative, sha256=sha, size_bytes=size, inputs=[], full_decode=True,
                         seam_decode=True, packet_chain=True, native_audit=True, original_sources_no_audio=True,
                         readback_sha256=sha, fsynced=True)
            for clip, source in zip(run_clips, sources):
                # Fresh input hash and exact physical sidecar proof after all
                # child reads; a changed source invalidates the entire run.
                with CleanupFile(cfg, clip, stop, deadline) as current:
                    raw_proof = current.proof()
                proof["inputs"].append(dict(clip_id=clip["source_id"], sha256=clip["sha256"], size_bytes=clip["size_bytes"],
                                             packet_chain_sha256=source["chain"], packets=source["count"], frames=source["count"],
                                             repaired=False, retirement_held=clip["source_id"] in held, raw_proof=raw_proof))
            proof_temp = work / "proof.partial.json"
            proof_temp.write_bytes(cleanup_json_bytes(proof))
            directory.publish(proof_temp.name, name + ".proof.json")
            result["outputs"].append(proof)
            STITCH_STATUS.add("outputs_verified")
            run_index += 1
            sources, run_clips = [], []

        for index, original in enumerate(clips):
            if stop.is_set():
                raise StitchHold(stop.reason or "stitch cancelled")
            clip = dict(original)
            # Reuse the independent pinned folder/keep-window map for scope.
            pins, error = cleanup_pins()
            key = cleanup_folder_key(clip["relative_path"], "raw")
            if error or pins["folders"].get(key) != plan["stream_id"] or clip["stream_id"] != plan["stream_id"]:
                raise StitchHold("raw folder is not owned by approved stream")
            start, end, _ = pins["windows"][plan["stream_id"]]
            a = parse_certification_timestamp(clip["start_at"], "source start")
            b = parse_certification_timestamp(clip["end_at"], "source end")
            if a < start or b > end or b <= a:
                raise StitchHold("source crosses keep boundary")
            path, info, _ = hash_certification_file(cfg.output_dir, clip["relative_path"], clip["size_bytes"], clip["sha256"])
            if sys.platform.startswith("linux"):
                fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW)
                resources.callback(os.close, fd)
                if cleanup_identity(os.fstat(fd)) != cleanup_identity(info):
                    raise StitchHold("source identity changed before native audit")
                path = Path("/proc/%d/fd/%d" % (os.getpid(), fd))
            sidecar, scinfo = confined_regular_file(cfg.output_dir, clip["relative_path"] + ".stoarama.json")
            clip.update(frozen_identity=cleanup_identity(info), frozen_sidecar_identity=cleanup_identity(scinfo), _path=path)
            if not plan["eligible"][index] or (admitted is not None and not admitted(clip)):
                flush()
                repaired = stitch_repair_local(cfg, clip, path, directory, tools, deadline, stop)
                if repaired:
                    result["repairs"].append(repaired)
                result["left_out"].append(clip["source_id"])
                continue
            try:
                source = stitch_audit_source(ffmpeg, ffprobe, path, work, index, deadline, stop)
            except StitchHold as exc:
                if stop.is_set():
                    raise
                flush()
                repaired = stitch_repair_local(cfg, clip, path, directory, tools, deadline, stop)
                if repaired:
                    result["repairs"].append(repaired)
                result["left_out"].append(clip["source_id"])
                log("WARN", "V85r source retained clip=%s: %s" % (clip["source_id"], exc))
                continue
            if sources and (not result["seams"][index-1].get("join")
                            or sources[-1]["signature"] != source["signature"]):
                flush()
            sources.append(source)
            run_clips.append(clip)
        flush()
    stitch_journal(inventory, task["id"], task["plan_sha256"], result)
    return result


def stitch_register(cfg, inventory, task_id, result):
    for output in result["outputs"] + result.get("repairs", []):
        hash_certification_file(cfg.output_dir, output["relative_path"], output["size_bytes"], output["sha256"])
    ack = restore_api(cfg, "/account/connections/stitch/%d/result" % task_id, result)
    if ack.get("recorded") is not True or ack.get("id") != task_id:
        raise StitchHold("server output registration not acknowledged")
    for output in result["outputs"]:
        relative = Path(output["relative_path"])
        with StitchDirectory(cfg.output_dir, str(relative.parent)) as directory:
            receipt = dict(recorded=True, task_id=task_id, plan_sha256=result["plan_sha256"], sha256=output["sha256"])
            temporary = directory.path / "registration.partial.json"
            temporary.write_bytes(cleanup_json_bytes(receipt))
            directory.publish(temporary.name, relative.name + ".registered.json")
    ready = restore_api(cfg, "/account/connections/stitch/%d/ready" % task_id,
                        dict(lease_token=result["lease_token"], plan_sha256=result["plan_sha256"], outputs_ready=True))
    if ready.get("ready") is not True or ready.get("id") != task_id:
        raise StitchHold("server cleanup readiness not acknowledged")
    stitch_journal(inventory, task_id, result["plan_sha256"], result, registered=True)
    STITCH_STATUS.update(state="registered", completed_at=utc_now())
    log("INFO", "V85r task=%s registered outputs=%d retained=%d" % (task_id, len(result["outputs"]), len(result["left_out"])))


def stitch_once(cfg, inventory, stop_event):
    # Registration reconciliation needs no growing media allocation. A crash
    # after server commit but before local receipt must complete this gate.
    stitch_journal(inventory, 0, "")
    with inventory.lock:
        pending = inventory.db.execute("SELECT task_id,result FROM stitch_jobs WHERE registered=0 AND result IS NOT NULL ORDER BY task_id LIMIT 1").fetchone()
    if pending:
        try:
            stitch_register(cfg, inventory, pending[0], json.loads(pending[1]))
            return 30
        except urllib.error.HTTPError as exc:
            if exc.code != 409:
                raise
            # An uncommitted expired lease needs its new token below. An
            # already committed result always answers idempotently first.
    stitch_resources(cfg)
    response = restore_api(cfg, "/account/connections/stitch/lease", {"client_version": CLIENT_VERSION})
    task = response.get("task")
    if task is None:
        return max(30, min(600, response.get("retry_after_sec", 300)))
    STITCH_STATUS.update(task_id=task["id"], state="working", started_at=utc_now())
    stitch_resources(cfg, sum(c["size_bytes"] for c in task["plan"]["clips"]))
    result = stitch_journal(inventory, task["id"], task["plan_sha256"])
    if result is None:
        stitch_corpus(cfg, inventory)
        tools = stitch_v85r_tools(cfg, time.monotonic() + BENCHMARK_TOOL_INSTALL_SEC, stop_event)
        result = stitch_build(cfg, inventory, task, stop_event, tools)
    result["lease_token"] = task["lease_token"]
    stitch_journal(inventory, task["id"], task["plan_sha256"], result)
    stitch_register(cfg, inventory, task["id"], result)
    return 30


def stitch_loop(cfg, inventory, stop_event):
    try:
        stitch_priority()
    except Exception as exc:
        STITCH_STATUS.fail(str(exc))
        log("ERROR", "V85r stitch lane disabled: %s" % exc)
        return
    while not stop_event.is_set():
        retry = 60
        try:
            STITCH_ACTIVE.set()
            retry = stitch_once(cfg, inventory, stop_event)
        except Exception as exc:
            STITCH_STATUS.update(state="paused")
            STITCH_STATUS.fail(str(exc))
            log("WARN", "V85r stitch HOLD: %s" % str(exc)[:300])
        finally:
            STITCH_ACTIVE.clear()
        stop_event.wait(retry)


def valid_benchmark_task(task):
    if not isinstance(task, dict):
        raise BenchmarkError("invalid benchmark task")
    benchmark_id = task.get("benchmark_id")
    clips = task.get("clips")
    deadline = task.get("deadline_sec")
    if type(benchmark_id) is not int or benchmark_id <= 0:
        raise BenchmarkError("invalid benchmark id")
    if type(deadline) is not int or deadline <= 0:
        raise BenchmarkError("invalid benchmark deadline")
    if not isinstance(clips, list) or not 1 <= len(clips) <= BENCHMARK_MAX_CLIPS:
        raise BenchmarkError("invalid benchmark clip list")
    valid = []
    for clip in clips:
        if not isinstance(clip, dict):
            raise BenchmarkError("invalid benchmark clip")
        size, sha = clip.get("size_bytes"), str(clip.get("sha256", ""))
        if type(size) is not int or size <= 0 or len(sha) != 64 or any(ch not in "0123456789abcdef" for ch in sha):
            raise BenchmarkError("invalid benchmark clip identity")
        valid.append({"clip_id": clip.get("clip_id"), "relative_path": str(clip.get("relative_path", "")),
                      "size_bytes": size, "sha256": sha})
    return benchmark_id, min(deadline, BENCHMARK_MAX_DEADLINE_SEC), valid


def run_benchmark(cfg, task, stop_event, host_facts, tool_installer=ensure_benchmark_tools):
    """Execute one benchmark task. Returns (status, error, result)."""
    benchmark_id, deadline_sec, clips = valid_benchmark_task(task)
    try:
        os.setpriority(os.PRIO_PROCESS, threading.get_native_id(), BENCHMARK_NICE)
    except (AttributeError, OSError):
        pass
    started = time.monotonic()
    result = {"schema_version": 1, "benchmark_id": benchmark_id, "threads": BENCHMARK_THREADS,
              "nice": BENCHMARK_NICE, "clips": len(clips), "input_bytes": sum(c["size_bytes"] for c in clips),
              "media_seconds": 0.0, "deadline_sec": deadline_sec, "deadline_hit": False,
              "tool": {}, "stages": {}, "temp_removed": None}
    stages = result["stages"]
    status, error = "ok", ""
    work = Path(cfg.state_dir) / BENCHMARK_ROOT / str(benchmark_id)
    try:
        # Tool install: once per NAS, with its own cap; it is not collation cost.
        meter = StageMeter()
        try:
            tools = tool_installer(cfg.state_dir, host_facts.get("machine"), time.monotonic() + BENCHMARK_TOOL_INSTALL_SEC)
        except BenchmarkUnsupported as exc:
            stages["tool_install"] = meter.finish(include_thread=True, ok=False, error=str(exc)[:300])
            return "unsupported_arch", str(exc)[:1000], result
        except Exception as exc:
            stages["tool_install"] = meter.finish(include_thread=True, ok=False, error=str(exc)[:300])
            return "error", ("tool install failed: %s" % exc)[:1000], result
        stages["tool_install"] = meter.finish(include_thread=True, ok=True, source=tools.get("source", ""))
        result["tool"] = {key: value for key, value in tools.items() if key not in ("ffmpeg", "ffprobe")}
        ffmpeg, ffprobe = tools["ffmpeg"], tools["ffprobe"]
        version = run_measured([ffmpeg, "-hide_banner", "-version"], time.monotonic() + 60, stop_event, niced=False)
        result["tool"]["exec_ok"] = version["returncode"] == 0
        if version["returncode"] != 0:
            return "error", ("pinned ffmpeg does not execute: %s" % version["stderr"])[:1000], result

        deadline = time.monotonic() + deadline_sec
        import shutil as shutil_module
        clean_benchmark_root(cfg.state_dir)
        free = shutil_module.disk_usage(str(cfg.state_dir)).free
        needed = int(result["input_bytes"] * 1.1) + BENCHMARK_STATE_HEADROOM_BYTES
        if free < needed:
            return "error", "state volume has %d free bytes; benchmark needs %d" % (free, needed), result
        work.mkdir(parents=True, exist_ok=False)

        # 1. Read and hash every input exactly as collation would.
        meter = StageMeter()
        paths = []
        for clip in clips:
            if time.monotonic() > deadline:
                raise BenchmarkDeadline("benchmark deadline reached")
            if stop_event.is_set():
                raise BenchmarkError("client shutting down")
            path, file_stat = confined_regular_file(cfg.output_dir, clip["relative_path"])
            if file_stat.st_size != clip["size_bytes"]:
                stages["hash_inputs"] = meter.finish(include_thread=True, ok=False, error="size mismatch clip %s" % clip["clip_id"])
                return "error", "input size mismatch", result
            _, digest = sha256_file(path)
            if digest != clip["sha256"]:
                stages["hash_inputs"] = meter.finish(include_thread=True, ok=False, error="sha256 mismatch clip %s" % clip["clip_id"])
                return "error", "input sha256 mismatch", result
            paths.append(path)
        stages["hash_inputs"] = meter.finish(include_thread=True, ok=True, bytes=result["input_bytes"])

        # 2. Exact per-clip durations (what the concat manifest will pin).
        meter = StageMeter()
        durations, audio_clips = [], 0
        for index, path in enumerate(paths):
            probe_out = work / ("probe-%d.json" % index)
            measured = run_measured([ffprobe, "-v", "error", "-show_entries", "format=duration:stream=codec_type",
                                     "-of", "json", str(path)], deadline, stop_event, stdout_path=probe_out)
            meter.add(measured)
            try:
                parsed = json.loads(probe_out.read_text(encoding="utf-8"))
                durations.append(float(parsed["format"]["duration"]))
                audio_clips += any(s.get("codec_type") == "audio" for s in parsed.get("streams", []))
            except (ValueError, KeyError, TypeError, OSError):
                durations.append(None)
            probe_out.unlink()
        known = [d for d in durations if d]
        result["media_seconds"] = round(sum(known), 3)
        stages["probe"] = meter.finish(ok=len(known) == len(paths), clips_with_audio=audio_clips)

        # 3. Remux: concat demuxer, stream copy, no timestamp auto-conversion.
        meter = StageMeter()
        manifest = work / "concat.txt"
        manifest.write_text(benchmark_concat_manifest(paths, durations), encoding="utf-8")
        output = work / "joined.mp4"
        measured = run_measured([ffmpeg, "-nostdin", "-v", "error", "-protocol_whitelist", MEDIA_CERTIFICATION_PROTOCOLS,
                                 "-f", "concat", "-safe", "0", "-auto_convert", "0", "-i", str(manifest),
                                 "-map", "0:v:0", "-map", "0:a?", "-c", "copy", "-threads", str(BENCHMARK_THREADS),
                                 "-y", str(output)], deadline, stop_event)
        meter.add(measured)
        output_bytes = output.stat().st_size if output.exists() else 0
        stages["remux"] = meter.finish(ok=measured["returncode"] == 0 and output_bytes > 0, output_bytes=output_bytes,
                                       error=measured["stderr"][:300] if measured["returncode"] else "")
        if not stages["remux"]["ok"]:
            return "error", "remux failed", result

        # 4. Packet hash chain: every source packet payload, in order, per stream.
        meter = StageMeter()
        source_digests, source_counts = {}, {}
        hash_out = work / "framehash.txt"
        for path in paths:
            measured = run_measured([ffmpeg, "-nostdin", "-v", "error", "-i", str(path), "-map", "0:v:0", "-map", "0:a?",
                                     "-c", "copy", "-f", "framehash", "-hash", "sha256", "-y", str(hash_out)],
                                    deadline, stop_event)
            meter.add(measured)
            if measured["returncode"] != 0:
                stages["packet_chain"] = meter.finish(ok=False, error=measured["stderr"][:300])
                return "error", "source packet hash failed", result
            parse_framehash(hash_out, source_digests, source_counts)
            hash_out.unlink()
        measured = run_measured([ffmpeg, "-nostdin", "-v", "error", "-i", str(output), "-map", "0:v:0", "-map", "0:a?",
                                 "-c", "copy", "-f", "framehash", "-hash", "sha256", "-y", str(hash_out)],
                                deadline, stop_event)
        meter.add(measured)
        output_digests, output_counts, violations = parse_framehash(hash_out, check_timing=True)
        hash_out.unlink()
        match = (measured["returncode"] == 0 and source_counts == output_counts and
                 {k: v.hexdigest() for k, v in source_digests.items()} == {k: v.hexdigest() for k, v in output_digests.items()})
        stages["packet_chain"] = meter.finish(ok=measured["returncode"] == 0, match=match,
                                              source_packets=source_counts, output_packets=output_counts,
                                              dts_violations=violations)

        # 5. Seam-only decode: a short strict decode around every clip boundary.
        meter = StageMeter()
        seams, failures, offset = 0, 0, 0.0
        for duration in durations[:-1]:
            if not duration:
                break
            offset += duration
            start = max(0.0, offset - BENCHMARK_SEAM_HALF_WINDOW_SEC)
            measured = run_measured([ffmpeg, "-nostdin", "-v", "error", "-xerror", "-threads", str(BENCHMARK_THREADS),
                                     "-ss", "%.3f" % start, "-i", str(output), "-t", "%.3f" % (2 * BENCHMARK_SEAM_HALF_WINDOW_SEC),
                                     "-map", "0:v:0", "-map", "0:a?", "-f", "null", "-"], deadline, stop_event)
            meter.add(measured)
            seams += 1
            failures += measured["returncode"] != 0
        stages["seam_decode"] = meter.finish(ok=failures == 0, seams=seams, failures=failures)

        # 6. Full strict decode of the whole output.
        meter = StageMeter()
        measured = run_measured([ffmpeg, "-nostdin", "-v", "error", "-xerror", "-err_detect", "explode",
                                 "-threads", str(BENCHMARK_THREADS), "-i", str(output),
                                 "-map", "0:v:0", "-map", "0:a?", "-f", "null", "-"], deadline, stop_event)
        meter.add(measured)
        stages["full_decode"] = meter.finish(ok=measured["returncode"] == 0,
                                             error=measured["stderr"][:300] if measured["returncode"] else "")
        if not (stages["packet_chain"]["match"] and stages["seam_decode"]["ok"] and stages["full_decode"]["ok"]):
            error = "verification findings: packet_match=%s seam_failures=%d full_decode_ok=%s" % (
                match, failures, stages["full_decode"]["ok"])
        return status, error, result
    except BenchmarkDeadline as exc:
        result["deadline_hit"] = True
        return "partial", str(exc), result
    except MediaCertificationError as exc:
        return "error", ("input path rejected: %s" % exc)[:1000], result
    except Exception as exc:
        return "error", ("%s: %s" % (type(exc).__name__, exc))[:1000], result
    finally:
        if work.exists():
            clean_benchmark_root(cfg.state_dir)
            result["temp_removed"] = not work.exists()
        elif "hash_inputs" in stages:
            result["temp_removed"] = True
        result["total_wall_s"] = round(time.monotonic() - started, 3)


def report_benchmark(cfg, benchmark_id, body, sleep=time.sleep):
    for attempt in range(1, BENCHMARK_REPORT_ATTEMPTS + 1):
        try:
            request_json(cfg, "POST", "/account/connections/benchmark/%d/result" % benchmark_id,
                         body=body, timeout=HEARTBEAT_TIMEOUT_SEC)
            return
        except urllib.error.HTTPError as exc:
            if exc.code == 409:
                return
            if not transient_error(exc) or attempt == BENCHMARK_REPORT_ATTEMPTS:
                raise
        except Exception as exc:
            if not transient_error(exc) or attempt == BENCHMARK_REPORT_ATTEMPTS:
                raise
        sleep(BENCHMARK_REPORT_BACKOFF_SEC * attempt)


def benchmark_once(cfg, stop_event, host_facts):
    """Claim a benchmark if one is requested, run it, report it. Returns the wait."""
    facts = host_facts()
    claimed = request_json(cfg, "POST", "/account/connections/benchmark/claim",
                           body={"client_version": CLIENT_VERSION, "host": facts}, timeout=HEARTBEAT_TIMEOUT_SEC)
    if not isinstance(claimed, dict):
        raise BenchmarkError("invalid benchmark claim response")
    retry_after = claimed.get("retry_after_sec", BENCHMARK_ERROR_WAIT_SEC)
    task = claimed.get("task")
    if claimed.get("enabled") is not True or not isinstance(task, dict):
        return retry_after
    BENCHMARK_ACTIVE.set()
    try:
        status, error, result = run_benchmark(cfg, task, stop_event, facts)
    finally:
        BENCHMARK_ACTIVE.clear()
    if stop_event.is_set() and status != "ok":
        # A shutdown cut it short; the lease expires and the server re-offers it.
        return retry_after
    report_benchmark(cfg, task["benchmark_id"], {
        "client_version": CLIENT_VERSION, "status": status, "error": error[:1000], "host": host_facts(),
        "result": result,
    })
    log("INFO" if status == "ok" else "WARN", "benchmark id=%d status=%s media=%.0fs wall=%.0fs%s" % (
        task["benchmark_id"], status, result.get("media_seconds", 0), result.get("total_wall_s", 0),
        (" error=%s" % error) if error else ""))
    return retry_after


def benchmark_wait(seconds, rng=random):
    try:
        seconds = int(seconds)
    except (TypeError, ValueError):
        seconds = BENCHMARK_ERROR_WAIT_SEC
    return min(max(seconds, BENCHMARK_MIN_WAIT_SEC), BENCHMARK_MAX_WAIT_SEC) * rng.uniform(0.9, 1.1)


def benchmark_loop(cfg, runtime, stop_event, rng=random):
    """Background benchmark poller; never raises."""
    wait = rng.uniform(*BENCHMARK_STARTUP_DELAY_SEC)
    while not stop_event.wait(wait):
        try:
            wait = benchmark_wait(benchmark_once(cfg, stop_event, runtime.host_facts), rng)
        except Exception as exc:
            log("WARN", "benchmark deferred: %s" % exc)
            wait = benchmark_wait(BENCHMARK_ERROR_WAIT_SEC, rng)



def validate_manifest(manifest):
    version = str(manifest.get("version", ""))
    artifact = str(manifest.get("artifact", ""))
    sha256 = str(manifest.get("sha256", "")).lower()
    if not version or len(version) > 64 or any(ch not in "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-" for ch in version):
        raise RuntimeError("invalid update version")
    if not artifact or "/" in artifact or "\\" in artifact or artifact in (".", ".."):
        raise RuntimeError("invalid update artifact")
    if len(sha256) != 64 or any(ch not in "0123456789abcdef" for ch in sha256):
        raise RuntimeError("invalid update sha256")
    return version, artifact, sha256


def stage_update(cfg):
    manifest = request_json(cfg, "GET", cfg.update_manifest_url, authenticate=False, timeout=30)
    version, artifact, expected_sha = validate_manifest(manifest)
    if version == CLIENT_VERSION:
        return None
    artifact_url = cfg.update_manifest_url.rsplit("/", 1)[0] + "/" + artifact
    req = urllib.request.Request(artifact_url, headers={"User-Agent": USER_AGENT})
    with urllib.request.urlopen(req, timeout=30) as response:
        remember_response_secrets(response)
        source = response.read()
    if hashlib.sha256(source).hexdigest() != expected_sha:
        raise RuntimeError("update artifact checksum mismatch")
    compile(source, artifact, "exec")
    with CANDIDATE_UPDATE_LOCK:
        atomic_write(cfg.candidate_file, source, mode=0o700)
    log("INFO", "staged NAS pull client version=%s" % version)
    return version


def update_loop(cfg, runtime, stop_event, inventory_stop_event, update_ready, joined_stop_event=None):
    while not stop_event.is_set():
        try:
            if stage_update(cfg):
                # Staging is harmless, but process replacement is not. Ask the
                # background inventory scan to stop at a durable checkpoint;
                # both delivery loops remain live while their active page or
                # joined range reaches a durable boundary.
                inventory_stop_event.set()
                if joined_stop_event is not None:
                    joined_stop_event.set()
                update_ready.set()
                return
        except Exception as exc:
            log("WARN", "self-update check failed: %s" % exc)
        stop_event.wait(UPDATE_INTERVAL_SEC)


def executing_release_sha256(cfg):
    # CLIENT_VERSION is a literal in the code this interpreter compiled.
    # The immutable version-specific manifest binds that boot to its approved
    # full source hash, even if an external stager replaced __file__ at startup.
    expected = getattr(cfg, "executing_release_sha256", None)
    if expected is not None:
        return expected
    url = cfg.update_manifest_url.rsplit("/", 1)[0] + "/latest-" + CLIENT_VERSION + ".json"
    manifest = request_json(cfg, "GET", url, authenticate=False, timeout=10)
    version, artifact, expected = validate_manifest(manifest)
    if version != CLIENT_VERSION or artifact != "stoarama-pull-" + CLIENT_VERSION + ".py":
        raise RuntimeError("executing release identity is unavailable")
    cfg.executing_release_sha256 = expected
    return expected


class CandidateMismatch(RuntimeError):
    """A newer staged artifact must be executed before it can be healthy."""


def promote_candidate(cfg):
    if not cfg.is_candidate:
        return
    expected = executing_release_sha256(cfg)
    # The updater may already have staged another version at candidate_file.
    # Bind promotion to the artifact this boot actually executed, and serialize
    # its hash/rename with staging to close the check-to-rename race.
    with CANDIDATE_UPDATE_LOCK:
        if not cfg.is_candidate:
            return
        source = cfg.candidate_file.read_bytes()
        if hashlib.sha256(source).hexdigest() != expected:
            raise CandidateMismatch("staged candidate differs from executing release; defer promotion")
        if cfg.current_file.exists():
            atomic_write(cfg.previous_file, cfg.current_file.read_bytes(), mode=0o700)
        # Install the captured verified bytes, never a mutable path. A separate
        # self-update process can replace candidate_file without our thread lock.
        # Leave that path intact so its newer candidate is not lost or promoted.
        atomic_write(cfg.current_file, source, mode=0o700)
        fsync_dir(cfg.state_dir)
        cfg.is_candidate = False
        log("INFO", "promoted candidate version=%s" % CLIENT_VERSION)


def exec_candidate(cfg, runtime):
    mark_runtime(cfg, runtime, PreviousExit.SELF_UPDATE.value)
    env = os.environ.copy()
    env["STOARAMA_CANDIDATE"] = "1"
    try:
        os.execve(sys.executable, [sys.executable, str(cfg.candidate_file), "run"], env)
    except OSError as exc:
        raise SelfUpdateExecError("failed to activate staged NAS client") from exc


def update_can_exec(update_ready, inventory_worker, stop_event=None, joined_worker=None, cleanup_worker=None):
    """Process replacement is safe only between delivery pages and scans."""
    return (
        update_ready.is_set()
        and (stop_event is None or not stop_event.is_set())
        and not inventory_worker.is_alive()
        and (joined_worker is None or not joined_worker.is_alive())
        and (cleanup_worker is None or not cleanup_worker.is_alive())
        and not BENCHMARK_ACTIVE.is_set()
        and not STITCH_ACTIVE.is_set()
    )


SPACE_AUDIT_SCHEMA = "nas-space-stat-v1-20261019"
# One new metadata walk; prior owned checkpoints and artifacts remain intact.
SPACE_AUDIT_EPOCH = "folder-closure-20261031"
SPACE_AUDIT_MAX_BYTES = 2 * 1024 * 1024 * 1024
SPACE_AUDIT_STATE_RESERVE = 256 * 1024 * 1024
SPACE_AUDIT_SQLITE_APPLICATION_ID = 0x53534131


class SpaceAudit:
    """One resumable metadata walk; never opens media files or follows links.

    The SQLite checkpoint and compressed report live on the app state volume.
    They are separate from the existing raw inventory, which skips joined/.
    """

    def __init__(self, cfg):
        self.cfg = cfg
        self.root = cfg.output_dir
        self.root_fd = self.state_fd = self.checkpoint_fd = None
        self.db = None
        try:
            self._initialize()
        except BaseException:
            self.close()
            raise

    def _initialize(self):
        for path in (self.root, self.cfg.state_dir):
            if not stat_module.S_ISDIR(os.lstat(path).st_mode) or not os.path.ismount(str(path)):
                raise RuntimeError("space audit requires mounted directories")
        flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW
        self.root_fd = os.open(str(self.root), flags)
        self.state_fd = os.open(str(self.cfg.state_dir), flags)
        info, state = os.fstat(self.root_fd), os.fstat(self.state_fd)
        self.root_identity = (info.st_dev, info.st_ino)
        self.state_identity = (state.st_dev, state.st_ino)
        if self.root_identity == self.state_identity:
            raise RuntimeError("space audit clips and state mounts must differ")
        self.device = info.st_dev
        self.check_scope()
        identity = "%d:%d" % self.root_identity
        # A remounted/replaced root starts a new generation, preserving every
        # prior checkpoint/report instead of declaring the detached root current.
        # Bind checkpoints to this authenticated origin too. Re-enrollment or
        # key rotation may start a fresh audit, but cannot reuse another account's
        # completion. Credentials are never persisted in the checkpoint.
        context = json.dumps([identity, getattr(self.cfg, "api_base", ""),
                              getattr(self.cfg, "api_key", ""), SPACE_AUDIT_EPOCH], ensure_ascii=True)
        generation = hashlib.sha256(context.encode("ascii")).hexdigest()[:24]
        prefix = SPACE_AUDIT_SCHEMA + "-" + generation
        self.checkpoint_owner_key = hashlib.sha256(("checkpoint-owner:" + context).encode("ascii")).digest()
        self.artifact_base = prefix + ".jsonl.gz"
        self.artifact = self.cfg.state_dir / (prefix + ".jsonl.gz")
        self.open_checkpoint(prefix)
        # Linux can anchor SQLite and its journal to the already-pinned private
        # directory even if a configured pathname changes concurrently.
        sqlite_path = ("/proc/self/fd/%d/checkpoint.sqlite3" % self.checkpoint_fd
                       if sys.platform.startswith("linux") else str(self.path))
        self.db = sqlite3.connect(sqlite_path, timeout=30)
        self.db.execute("PRAGMA locking_mode=EXCLUSIVE")
        if self.db.execute("PRAGMA journal_mode=PERSIST").fetchone()[0] != "persist":
            raise RuntimeError("space audit persistent journal unavailable")
        self.db.execute("PRAGMA application_id=%d" % SPACE_AUDIT_SQLITE_APPLICATION_ID)
        self.check_scope()
        self.check_checkpoint_files()
        self.db.executescript("""
            CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
            CREATE TABLE IF NOT EXISTS dirs (path TEXT PRIMARY KEY, done INTEGER NOT NULL DEFAULT 0);
            CREATE INDEX IF NOT EXISTS dirs_pending_idx ON dirs(done,path);
            CREATE TABLE IF NOT EXISTS directory_closure (path TEXT PRIMARY KEY, proof TEXT NOT NULL);
            CREATE TABLE IF NOT EXISTS entries (
                path TEXT PRIMARY KEY, folder TEXT NOT NULL, kind TEXT NOT NULL,
                category TEXT NOT NULL, size INTEGER NOT NULL, allocated INTEGER NOT NULL,
                device INTEGER NOT NULL, inode INTEGER NOT NULL, links INTEGER NOT NULL,
                mtime_ns INTEGER NOT NULL, ctime_ns INTEGER NOT NULL, error TEXT NOT NULL,
                observed_at TEXT NOT NULL);
            CREATE INDEX IF NOT EXISTS entries_inode_idx ON entries(device,inode,size,allocated) WHERE kind='file';
        """)
        if self.get("root_identity") not in (None, identity):
            raise RuntimeError("space audit root identity changed; previous report retained")
        if not self.get("audit_id"):
            for key, value in {"audit_id": str(uuid.uuid4()), "state": "scanning",
                               "started_at": utc_now(), "root_identity": identity,
                               "client_version": CLIENT_VERSION}.items():
                self.set(key, value)
            self.db.execute("INSERT OR IGNORE INTO dirs(path) VALUES (?)", (self.path_key(""),))
            self.db.commit()
        self.check_checkpoint_files()
        if self.get("artifact_name"):
            self.validate_report_name(self.get("artifact_name"))
            self.artifact = self.cfg.state_dir / self.get("artifact_name")
        if self.get("export_temporary"):
            # Recover capacity by truncating only the registered inode through
            # its verified descriptor. Never unlink or replace a report path.
            _, fd = self.open_export_temporary()
            os.close(fd)
        self.require_state_capacity()

    def close(self):
        if self.db is not None:
            self.db.close()
            self.db = None
        for name in ("checkpoint_fd", "root_fd", "state_fd"):
            fd = getattr(self, name, None)
            if fd is not None:
                os.close(fd)
                setattr(self, name, None)

    def check_scope(self):
        scopes = [(self.root, self.root_fd, self.root_identity),
                  (self.cfg.state_dir, self.state_fd, self.state_identity)]
        if self.checkpoint_fd is not None:
            current = os.lstat(self.path.parent)
            opened = os.fstat(self.checkpoint_fd)
            if not stat_module.S_ISDIR(current.st_mode) or (current.st_dev, current.st_ino) != (opened.st_dev, opened.st_ino):
                raise RuntimeError("space audit checkpoint directory changed")
        for path, fd, identity in scopes:
            current, opened = os.lstat(path), os.fstat(fd)
            if (not stat_module.S_ISDIR(current.st_mode) or not os.path.ismount(str(path))
                    or (current.st_dev, current.st_ino) != identity
                    or (opened.st_dev, opened.st_ino) != identity):
                raise RuntimeError("space audit mount identity changed")

    def checkpoint_signature(self, record):
        return hmac.new(self.checkpoint_owner_key,
                        json.dumps(record, sort_keys=True, separators=(",", ":")).encode("ascii"),
                        hashlib.sha256).hexdigest()

    def check_checkpoint_files(self):
        for name, identity in self.checkpoint_record["files"].items():
            info = os.stat(name, dir_fd=self.checkpoint_fd, follow_symlinks=False)
            if (not stat_module.S_ISREG(info.st_mode) or info.st_nlink != 1
                    or [info.st_dev, info.st_ino] != identity):
                raise RuntimeError("space audit checkpoint ownership changed")
            fd = os.open(name, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=self.checkpoint_fd)
            with os.fdopen(fd, "rb") as source:
                opened = os.fstat(source.fileno())
                if [opened.st_dev, opened.st_ino] != identity or opened.st_nlink != 1:
                    raise RuntimeError("space audit checkpoint identity changed")
                header = source.read(100 if name == "checkpoint.sqlite3" else 8)
            if name == "checkpoint.sqlite3":
                if header and (len(header) < 100 or header[:16] != b"SQLite format 3\x00"
                               or int.from_bytes(header[68:72], "big") != SPACE_AUDIT_SQLITE_APPLICATION_ID):
                    raise RuntimeError("space audit unknown database preserved")
            elif header not in (b"", b"\x00" * 8, bytes.fromhex("d9d505f920a163d7")):
                raise RuntimeError("space audit unknown journal preserved")
        # This checkpoint uses PERSIST rollback journaling, never WAL/shm.
        for suffix in ("-wal", "-shm"):
            try:
                os.stat("checkpoint.sqlite3" + suffix, dir_fd=self.checkpoint_fd, follow_symlinks=False)
            except FileNotFoundError:
                continue
            raise RuntimeError("space audit unknown SQLite sidecar preserved")

    def open_checkpoint(self, prefix):
        # A private allocation and authenticated inode record establish ownership
        # before SQLite can write or clean up journals. Unknown files/directories
        # are bypassed intact, including interrupted allocations without a record.
        pattern = re.compile(re.escape(prefix) + r"\.checkpoint\.[0-9a-f]{32}")
        candidates = []
        for name in os.listdir(self.state_fd):
            if not pattern.fullmatch(name):
                continue
            directory_fd = None
            try:
                directory_fd = os.open(name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=self.state_fd)
                directory = os.fstat(directory_fd)
                if directory.st_dev != self.state_identity[0] or directory.st_mode & 0o077:
                    continue
                fd = os.open("owner.json", os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=directory_fd)
                with os.fdopen(fd, "rb") as source:
                    info = os.fstat(source.fileno())
                    if not stat_module.S_ISREG(info.st_mode) or info.st_nlink != 1 or info.st_size > 8192:
                        continue
                    envelope = json.loads(source.read(8193))
                record = envelope["record"]
                if (record["context"] != prefix or record["schema"] != 1
                        or set(record["files"]) != {"checkpoint.sqlite3", "checkpoint.sqlite3-journal"}
                        or not hmac.compare_digest(envelope["signature"], self.checkpoint_signature(record))):
                    continue
                self.checkpoint_fd, self.checkpoint_record = directory_fd, record
                try:
                    self.check_checkpoint_files()
                finally:
                    self.checkpoint_fd = None
                candidates.append((int(record["created_at_ns"]), name, record))
            except (OSError, RuntimeError, ValueError, KeyError, TypeError):
                continue
            finally:
                if directory_fd is not None:
                    os.close(directory_fd)
        if candidates:
            _, name, self.checkpoint_record = max(candidates, key=lambda item: item[0])
            self.checkpoint_fd = os.open(name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=self.state_fd)
        else:
            self.require_state_capacity()
            name = prefix + ".checkpoint." + uuid.uuid4().hex
            os.mkdir(name, 0o700, dir_fd=self.state_fd)
            self.checkpoint_fd = os.open(name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=self.state_fd)
            files = {}
            for filename in ("checkpoint.sqlite3", "checkpoint.sqlite3-journal"):
                fd = os.open(filename, os.O_RDWR | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600, dir_fd=self.checkpoint_fd)
                with os.fdopen(fd, "wb") as output:
                    info = os.fstat(output.fileno())
                    files[filename] = [info.st_dev, info.st_ino]
                    os.fsync(output.fileno())
            self.checkpoint_record = {"schema": 1, "context": prefix,
                                      "created_at_ns": time.time_ns(), "files": files}
            envelope = {"record": self.checkpoint_record,
                        "signature": self.checkpoint_signature(self.checkpoint_record)}
            fd = os.open("owner.json", os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600, dir_fd=self.checkpoint_fd)
            with os.fdopen(fd, "w", encoding="ascii") as output:
                json.dump(envelope, output, ensure_ascii=True)
                output.flush()
                os.fsync(output.fileno())
            os.fsync(self.checkpoint_fd)
            os.fsync(self.state_fd)
        self.path = self.cfg.state_dir / name / "checkpoint.sqlite3"
        self.check_checkpoint_files()

    def require_state_capacity(self):
        volume = os.fstatvfs(self.state_fd)
        if volume.f_bavail * (volume.f_frsize or volume.f_bsize) < SPACE_AUDIT_STATE_RESERVE:
            raise RuntimeError("space audit state-volume reserve reached")

    def check_regular_file(self, name):
        info = os.stat(name, dir_fd=self.state_fd, follow_symlinks=False)
        if not stat_module.S_ISREG(info.st_mode) or info.st_nlink != 1 or info.st_dev != self.state_identity[0]:
            raise RuntimeError("space audit metadata path is not a private regular file")
        return info

    @staticmethod
    def path_key(path):
        # SQLite TEXT cannot encode surrogateescape. JSON ASCII is reversible,
        # including literal backslashes, so descriptor traversal keeps exact bytes.
        return json.dumps(path, ensure_ascii=True)

    @staticmethod
    def display_path(path):
        return path.encode("utf-8", "backslashreplace").decode("utf-8")

    @staticmethod
    def path_fields(path, key):
        fields = {key: SpaceAudit.display_path(path)}
        if any(0xD800 <= ord(char) <= 0xDFFF for char in path):
            fields[key + "_bytes_b64"] = base64.b64encode(os.fsencode(path)).decode("ascii")
        return fields

    def get(self, key):
        row = self.db.execute("SELECT value FROM meta WHERE key=?", (key,)).fetchone()
        return row[0] if row else None

    def set(self, key, value):
        self.db.execute("INSERT OR REPLACE INTO meta VALUES (?,?)", (key, str(value)))

    @staticmethod
    def folder(path):
        parts = path.split("/")
        return "/".join(parts[:3 if parts[0] == JOINED_ROOT else 2])

    @staticmethod
    def category(path, mode):
        if stat_module.S_ISLNK(mode):
            return "symlink_not_followed"
        if stat_module.S_ISDIR(mode):
            return "directory"
        if not stat_module.S_ISREG(mode):
            return "special_file"
        name = path.rsplit("/", 1)[-1].lower()
        if name.endswith((".part", ".partial", ".tmp", ".download")):
            return "temporary"
        if name.endswith((".mp4", ".mkv", ".mov", ".ts", ".webm", ".m4v", ".avi")):
            return "stitched_media" if path.startswith(JOINED_ROOT + "/") else "unstitched_media"
        if name.endswith((".json", ".jsonl", ".sqlite", ".sqlite3", ".db", ".txt", ".log", ".csv", ".sha256")):
            return "metadata"
        return "unknown"

    def record(self, path, info=None, error=""):
        mode = info.st_mode if info else 0
        kind = "directory" if stat_module.S_ISDIR(mode) else "file" if stat_module.S_ISREG(mode) else "other"
        values = (self.path_key(path), self.path_key(self.folder(path)), kind, self.category(path, mode) if info else "scan_error",
                  info.st_size if info and kind != "directory" else 0,
                  getattr(info, "st_blocks", 0) * 512 if info else 0,
                  info.st_dev if info else 0, info.st_ino if info else 0,
                  info.st_nlink if info else 0, info.st_mtime_ns if info else 0,
                  info.st_ctime_ns if info else 0, error, utc_now())
        inserted = self.db.execute(
            "INSERT INTO entries VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?) "
            "ON CONFLICT(path) DO NOTHING", values).rowcount
        if inserted not in (0, 1):
            raise RuntimeError("space audit insert count unavailable")
        if not inserted:
            updated = self.db.execute(
                "UPDATE entries SET folder=?,kind=?,category=?,size=?,allocated=?,device=?,"
                "inode=?,links=?,mtime_ns=?,ctime_ns=?,error=?,observed_at=? WHERE path=?",
                values[1:] + values[:1]).rowcount
            if updated != 1:
                raise RuntimeError("space audit replacement observation missing")
        if hasattr(self, "_progress_entry_count"):
            self._progress_entry_count += inserted
        if error:
            self._progress_errors_after_snapshot = getattr(self, "_progress_errors_after_snapshot", 0) + 1

    def open_directory(self, relative):
        fd = os.dup(self.root_fd)
        try:
            for part in relative.split("/") if relative else []:
                next_fd = os.open(part, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=fd)
                os.close(fd)
                fd = next_fd
            if os.fstat(fd).st_dev != self.device:
                raise OSError(errno.EXDEV, "nested filesystem excluded")
            return fd
        except BaseException:
            os.close(fd)
            raise

    @staticmethod
    def directory_identity(info):
        return [info.st_dev, info.st_ino, info.st_mtime_ns, info.st_ctime_ns]

    def direct_children(self, relative):
        # All keys are reversible ASCII JSON. A literal slash only separates
        # components, so this bounded primary-key range excludes descendants.
        prefix = self.path_key(relative + "/")[:-1] if relative else '"'
        return ("path>=? AND path<? AND instr(substr(path,?),'/')=0",
                (prefix, prefix + chr(127), len(prefix) + 1))

    def clear_partial_directory(self, relative):
        # Only this audit's metadata rows are replaced, never NAS entries.
        condition, values = self.direct_children(relative)
        removed = self.db.execute("DELETE FROM entries WHERE " + condition, values).rowcount
        if removed < 0:
            raise RuntimeError("space audit deletion count unavailable")
        if hasattr(self, "_progress_entry_count"):
            self._progress_entry_count -= removed
            if self._progress_entry_count < 0:
                raise RuntimeError("space audit progress count inconsistent")
        self.db.execute("DELETE FROM directory_closure WHERE path=?", (self.path_key(relative),))

    def finish_directory(self, relative, before, fd, started_at):
        after = os.fstat(fd)
        reopened = self.open_directory(relative)
        try:
            canonical = os.fstat(reopened)
        finally:
            os.close(reopened)
        stable = (self.directory_identity(before) == self.directory_identity(after)
                  == self.directory_identity(canonical))
        condition, values = self.direct_children(relative)
        digest, count = hashlib.sha256(), 0
        for row in self.db.execute(
                "SELECT path,kind,category,size,allocated,device,inode,links,mtime_ns,ctime_ns,error "
                "FROM entries WHERE " + condition + " ORDER BY path", values):
            digest.update(json.dumps(row, ensure_ascii=True, separators=(",", ":")).encode("ascii") + b"\n")
            count += 1
        proof = {"policy": "directory-observation-v1", "status": "stable" if stable else "changed",
                 "started_at": started_at, "completed_at": utc_now(), "direct_entries": count,
                 "children_sha256": digest.hexdigest(),
                 "before": self.directory_identity(before), "after": self.directory_identity(after),
                 "canonical_after": self.directory_identity(canonical)}
        self.db.execute("INSERT OR REPLACE INTO directory_closure VALUES (?,?)",
                        (self.path_key(relative), json.dumps(proof, separators=(",", ":"))))

    def scan(self, stop_event, progress):
        count = 0
        last_report = 0.0
        while not stop_event.is_set():
            self.check_scope()
            row = self.db.execute("SELECT path FROM dirs WHERE done=0 LIMIT 1").fetchone()
            if not row:
                self.check_scope()
                self.set("scan_completed_at", utc_now())
                self.set("final_summary", json.dumps(self.summary()))
                self.set("state", "exporting")
                self.db.commit()
                return True
            relative = json.loads(row[0])
            fd = None
            try:
                fd = self.open_directory(relative)
                before, started_at = os.fstat(fd), utc_now()
                # Failed parent enumeration may have discarded this queued
                # directory's entry. Restore only an absent row: existing rows
                # remain bound to the parent's observed-child digest.
                if relative and not self.db.execute(
                        "SELECT 1 FROM entries WHERE path=?", (self.path_key(relative),)).fetchone():
                    self.record(relative, before)
                self.clear_partial_directory(relative)
                with os.scandir(fd) as entries:
                    for entry in entries:
                        if stop_event.is_set():
                            self.db.commit()
                            return False
                        path = relative + "/" + entry.name if relative else entry.name
                        try:
                            info = entry.stat(follow_symlinks=False)
                            self.record(path, info)
                            if stat_module.S_ISDIR(info.st_mode):
                                if info.st_dev == self.device:
                                    self.db.execute("INSERT OR IGNORE INTO dirs(path) VALUES (?)", (self.path_key(path),))
                                else:
                                    self.record(path, info, "nested filesystem excluded")
                        except (OSError, OverflowError, UnicodeError) as exc:
                            self.record(path, error="stat %s errno=%s" % (type(exc).__name__, getattr(exc, "errno", None)))
                        count += 1
                        if count % 100 == 0:
                            self.check_scope()
                            self.require_state_capacity()
                            # NAS checkpoint fsync is expensive. Bound metadata
                            # transactions to 1,000 observations; directory,
                            # progress and cancellation exits still commit.
                            if count % 1000 == 0:
                                self.db.commit()
                            # About 2,000 stats/s maximum, below normal network delivery work.
                            if stop_event.wait(0.05):
                                return False
                        if time.monotonic() - last_report >= 60:
                            self.db.commit()
                            progress()
                            last_report = time.monotonic()
                self.finish_directory(relative, before, fd, started_at)
                self.db.execute("UPDATE dirs SET done=1 WHERE path=?", (row[0],))
            except OSError as exc:
                self.clear_partial_directory(relative)
                self.record(relative or ".", error="scandir errno=%s" % exc.errno)
                self.db.execute("UPDATE dirs SET done=1 WHERE path=?", (row[0],))
            finally:
                if fd is not None:
                    os.close(fd)
                self.db.commit()
        return False

    def progress_summary(self):
        """Cheap live counts; detailed fields retain their explicit snapshot time.

        Repeating category/folder/inode aggregation over a growing NAS SQLite
        checkpoint can spend longer reporting progress than walking entries.
        Only live scanning uses this cache. Final freezing/export still calls
        summary(), which computes every detailed field from the full checkpoint.
        """
        self.check_scope()
        frozen = self.get("final_summary")
        if frozen:
            return json.loads(frozen)
        if getattr(self, "_progress_details_json", None) is None:
            started = time.monotonic()
            details = self.summary()
            self._progress_entry_count = sum(c["entries"] for c in details["categories"])
            self._progress_details_json = json.dumps(details)
            self._progress_details_at = utc_now_precise()
            self._progress_details_seconds = max(0.0, time.monotonic() - started)
            self._progress_errors_after_snapshot = 0
        started = time.monotonic()
        result = json.loads(self._progress_details_json)
        entries = self._progress_entry_count
        pending = self.db.execute("SELECT count(*) FROM dirs WHERE done=0").fetchone()[0]
        closures = dict(self.db.execute(
            "SELECT json_extract(proof,'$.status'),count(*) FROM directory_closure GROUP BY 1"))
        errors = getattr(self, "_progress_errors_after_snapshot", 0)
        result.update(pending_directories=pending, directory_closure_counts=closures,
                      errors_or_exclusions=result["errors_or_exclusions"] + errors)
        result["scan_progress"] = {
            "policy": "checkpoint-count-v1", "checkpointed_entries": entries,
            "detailed_snapshot_at": self._progress_details_at,
            "detailed_snapshot_seconds": self._progress_details_seconds,
            "live_count_seconds": max(0.0, time.monotonic() - started),
            "errors_or_exclusions_is_upper_bound": True,
            "errors_observed_after_snapshot": errors,
            "cached_detailed_fields": [
                "categories", "folders", "folders_truncated", "root_directory_closure",
                "unique_regular_file_inodes", "unique_inode_allocated_bytes",
                "unique_inode_logical_bytes", "filesystem_total_bytes",
                "filesystem_available_bytes"],
            "consistency": "Live checkpoint counts; named detailed fields are the last "
                           "explicit snapshot, not current totals. Final artifact "
                           "always recomputes complete detailed statistics."}
        return result

    def summary(self):
        self.check_scope()
        frozen = self.get("final_summary")
        if frozen:
            return json.loads(frozen)
        columns = "category,count(*),coalesce(sum(size),0),coalesce(sum(allocated),0)"
        categories = [dict(zip(("category", "entries", "logical_bytes", "allocated_bytes_sum"), r))
                      for r in self.db.execute("SELECT " + columns + " FROM entries GROUP BY category")]
        folders = [dict(zip(("folder", "category", "entries", "logical_bytes", "allocated_bytes_sum"), r))
                   for r in self.db.execute("SELECT folder," + columns + " FROM entries GROUP BY folder,category ORDER BY folder,category LIMIT 2001")]
        for folder in folders:
            folder.update(self.path_fields(json.loads(folder["folder"]), "folder"))
        errors = self.db.execute("SELECT count(*) FROM entries WHERE error<>''").fetchone()[0]
        pending = self.db.execute("SELECT count(*) FROM dirs WHERE done=0").fetchone()[0]
        unique = self.db.execute("SELECT coalesce(sum(a),0),coalesce(sum(s),0),count(*) FROM (SELECT max(allocated) a,max(size) s FROM entries WHERE kind='file' GROUP BY device,inode)").fetchone()
        volume = os.statvfs(self.root_fd)
        closure_counts = dict(self.db.execute(
            "SELECT json_extract(proof,'$.status'),count(*) FROM directory_closure GROUP BY 1"))
        root_closure = self.db.execute("SELECT proof FROM directory_closure WHERE path=?",
                                       (self.path_key(""),)).fetchone()
        result = {"audit_epoch": SPACE_AUDIT_EPOCH, "directory_closure_counts": closure_counts,
                "root_directory_closure": json.loads(root_closure[0]) if root_closure else None,
                "schema": SPACE_AUDIT_SCHEMA, "root": str(self.root), "root_identity": self.get("root_identity"),
                "started_at": self.get("started_at"), "scan_completed_at": self.get("scan_completed_at"),
                "scope": "All entries under the app clips mount, including hidden files and joined/. No symlinks or cross-device directories followed. Other NAS shares, host-only folders and snapshots outside this mount are not observable.",
                "consistency": "Live non-atomic metadata walk. Directory closure binds direct-child observations only during each directory scan, not future contents or an atomic tree. Child payloads may change without changing directory timestamps. Changed/error/unobserved directories require KEEP. Incomplete scans replace their own partial child metadata on restart.",
                "classification": "Media classification is by location and extension; unstitched media duration is not measured. Allocated blocks are not unique physical extents or guaranteed reclaimable space.",
                "categories": categories, "folders": folders[:2000], "folders_truncated": len(folders) > 2000,
                "errors_or_exclusions": errors, "pending_directories": pending,
                "scan_complete": bool(self.get("scan_completed_at")) and pending == 0,
                "scope_complete_without_errors": bool(self.get("scan_completed_at")) and pending == 0 and errors == 0,
                "unique_regular_file_inodes": unique[2], "unique_inode_allocated_bytes": unique[0],
                "unique_inode_logical_bytes": unique[1],
                "filesystem_total_bytes": volume.f_blocks * volume.f_frsize,
                "filesystem_available_bytes": volume.f_bavail * volume.f_frsize}
        # Long Unicode names must not make the bounded API summary unreportable.
        # The compressed artifact still contains every per-file path and stat.
        while len(json.dumps(result).encode("utf-8")) > 900_000 and result["folders"]:
            result["folders"] = result["folders"][:len(result["folders"]) // 2]
            result["folders_truncated"] = True
        return result

    def report(self, state=None):
        body = {"audit_id": self.get("audit_id"), "state": state or self.get("state"),
                "client_version": self.get("client_version") or CLIENT_VERSION,
                "summary": self.progress_summary() if state == "scanning" else self.summary()}
        if self.get("artifact_sha256"):
            body.update(artifact_sha256=self.get("artifact_sha256"), artifact_size_bytes=int(self.get("artifact_size_bytes")))
        return request_json(self.cfg, "POST", "/account/connections/space-audit", body=body, timeout=30)

    def report_failure(self, exc):
        # Report loss of scope/headroom without reading the suspect mount or
        # presenting a stale frozen success summary as current evidence.
        body = {"audit_id": self.get("audit_id"), "state": "failed",
                "client_version": self.get("client_version") or CLIENT_VERSION,
                "summary": {"schema": SPACE_AUDIT_SCHEMA, "scan_complete": False,
                            "scope_complete_without_errors": False,
                            "error_class": type(exc).__name__, "errno": getattr(exc, "errno", None),
                            "observed_at": utc_now(), "checkpoint_retained": True}}
        return request_json(self.cfg, "POST", "/account/connections/space-audit", body=body, timeout=30)

    def validate_report_name(self, name):
        prefix = self.artifact_base + "."
        if not name.startswith(prefix) or not re.fullmatch(r"[0-9a-f]{32}\.tmp", name[len(prefix):]):
            raise RuntimeError("space audit report ownership record invalid")

    def open_export_temporary(self):
        # One pending inode is reused after interruption. Check the opened fd
        # before truncation; pathname swaps cannot redirect writes or deletion.
        pending = self.get("export_temporary")
        record = json.loads(pending) if pending else None
        name = record["name"] if record else self.artifact_base + "." + uuid.uuid4().hex + ".tmp"
        self.validate_report_name(name)
        self.check_scope()
        flags = os.O_RDWR | os.O_NOFOLLOW | os.O_NONBLOCK
        if not record:
            flags |= os.O_CREAT | os.O_EXCL
        fd = os.open(name, flags, 0o600, dir_fd=self.state_fd)
        try:
            info = os.fstat(fd)
            if (not stat_module.S_ISREG(info.st_mode) or info.st_nlink != 1
                    or info.st_dev != self.state_identity[0]
                    or (record and (info.st_dev, info.st_ino) != (record["device"], record["inode"]))):
                raise RuntimeError("space audit temporary ownership changed")
            if not record:
                os.fsync(self.state_fd)
                self.set("export_temporary", json.dumps({"name": name,
                         "device": info.st_dev, "inode": info.st_ino}))
                self.db.commit()
            self.check_scope()
            os.ftruncate(fd, 0)
            os.fsync(fd)
            return name, fd
        except BaseException:
            os.close(fd)
            raise

    def export(self, stop_event):
        # Only app-owned report metadata is written/read. No media is opened.
        self.check_scope()
        self.require_state_capacity()
        temporary, fd = self.open_export_temporary()
        with os.fdopen(fd, "w+b") as raw:
            info = os.fstat(raw.fileno())
            with gzip.GzipFile(filename="", mode="wb", fileobj=raw, mtime=0) as compressed:
                with io.TextIOWrapper(compressed, encoding="utf-8", newline="\n") as stream:
                    stream.write(json.dumps({"type": "summary", "audit_id": self.get("audit_id"), "summary": self.summary()}) + "\n")
                    names = [r[1] for r in self.db.execute("PRAGMA table_info(entries)")]
                    for count, row in enumerate(self.db.execute("SELECT * FROM entries ORDER BY path")):
                        if stop_event.is_set():
                            return False
                        entry = dict(zip(names, row))
                        if entry["kind"] == "directory":
                            closure = self.db.execute("SELECT proof FROM directory_closure WHERE path=?",
                                                       (entry["path"],)).fetchone()
                            entry["directory_closure"] = json.loads(closure[0]) if closure else None
                        for key in ("path", "folder"):
                            entry.update(self.path_fields(json.loads(entry[key]), key))
                        stream.write(json.dumps(entry, ensure_ascii=True, separators=(",", ":")) + "\n")
                        if count % 100 == 0:
                            self.check_scope()
                            self.require_state_capacity()
                            stream.flush()
                            if raw.tell() > SPACE_AUDIT_MAX_BYTES:
                                raise RuntimeError("space audit compressed report exceeds upload limit")
            # Finish the gzip trailer before making its identity durable.
            raw.flush()
            os.fsync(raw.fileno())
            raw.seek(0)
            size, digest = self.hash_report(raw, stop_event)
        if not 0 < size <= SPACE_AUDIT_MAX_BYTES:
            raise RuntimeError("space audit compressed report exceeds upload limit")
        if self.get("artifact_sha256") and (size != int(self.get("artifact_size_bytes")) or digest != self.get("artifact_sha256")):
            raise RuntimeError("regenerated space audit differs from its frozen declaration")
        self.check_scope()
        current = self.check_regular_file(temporary)
        if (current.st_dev, current.st_ino) != (info.st_dev, info.st_ino):
            raise RuntimeError("space audit report pathname changed")
        self.set("artifact_name", temporary)
        self.set("artifact_device", info.st_dev)
        self.set("artifact_inode", info.st_ino)
        self.set("artifact_sha256", digest)
        self.set("artifact_size_bytes", size)
        self.set("state", "uploading")
        self.db.execute("DELETE FROM meta WHERE key='export_temporary'")
        self.db.commit()
        self.artifact = self.cfg.state_dir / temporary
        return True

    @staticmethod
    def hash_report(source, stop_event):
        size, digest = 0, hashlib.sha256()
        for block in iter(lambda: source.read(1024 * 1024), b""):
            if stop_event.is_set():
                raise RuntimeError("space audit metadata hashing stopped")
            size += len(block)
            if size > SPACE_AUDIT_MAX_BYTES:
                raise RuntimeError("space audit metadata exceeds upload limit")
            digest.update(block)
        return size, digest.hexdigest()

    def open_verified_artifact(self, stop_event):
        self.check_scope()
        # Refuse links before opening. A pinned descriptor is hashed and then
        # handed directly to PUT; a later pathname swap cannot redirect reads.
        before = self.check_regular_file(self.artifact.name)
        if (str(before.st_dev), str(before.st_ino)) != (self.get("artifact_device"), self.get("artifact_inode")):
            raise RuntimeError("space audit artifact ownership changed")
        fd = os.open(self.artifact.name, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=self.state_fd)
        source = os.fdopen(fd, "rb")
        try:
            opened = os.fstat(fd)
            if (before.st_dev, before.st_ino) != (opened.st_dev, opened.st_ino) or not stat_module.S_ISREG(opened.st_mode) or opened.st_nlink != 1:
                raise RuntimeError("space audit artifact identity changed")
            size, digest = self.hash_report(source, stop_event)
            after = self.check_regular_file(self.artifact.name)
            if ((before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns, before.st_ctime_ns)
                    != (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns, after.st_ctime_ns)
                    or size != int(self.get("artifact_size_bytes")) or digest != self.get("artifact_sha256")):
                raise RuntimeError("space audit artifact size or SHA differs from its declaration")
            source.seek(0)
            return source
        except BaseException:
            source.close()
            raise

    def upload(self, target, source):
        self.check_scope()
        if not isinstance(target, dict):
            raise RuntimeError("space audit upload target missing")
        url = urllib.parse.urlsplit(str(target.get("url", "")))
        if (url.scheme != "https" or not url.hostname or not url.hostname.endswith(".r2.cloudflarestorage.com")
                or url.username or url.password or url.port not in (None, 443) or target.get("method") != "PUT"
                or target.get("size_bytes") != int(self.get("artifact_size_bytes"))):
            raise RuntimeError("invalid space audit upload target")
        headers = dict(target.get("headers") or {})
        headers["Content-Length"] = self.get("artifact_size_bytes")
        connection = http.client.HTTPSConnection(url.netloc, timeout=60, blocksize=1024 * 1024)
        try:
            connection.request("PUT", url.path + "?" + url.query, body=source, headers=headers)
            response = connection.getresponse()
            remember_response_secrets(response)
            if response.status not in (200, 201, 204, 412):
                raise RuntimeError("space audit upload HTTP %d" % response.status)
            # 412 is an idempotent create-only retry; the API checks exact HEAD identity.
            response.read(4096)
        finally:
            connection.close()


def space_audit_loop(cfg, stop_event, reported):
    if stop_event.wait(10):
        return
    while not stop_event.is_set():
        audit = None
        try:
            audit = SpaceAudit(cfg)
            if audit.get("state") == "complete":
                audit.report("complete")
                reported.set()
                return
            if audit.get("state") == "scanning":
                def progress():
                    try:
                        audit.report("scanning")
                        reported.set()
                    except Exception:
                        log("WARN", "space audit progress report deferred; local checkpoint retained")
                progress()
                if not audit.scan(stop_event, progress):
                    return
            if audit.get("state") == "exporting" and not audit.export(stop_event):
                return
            try:
                source = audit.open_verified_artifact(stop_event)
            except (OSError, RuntimeError):
                audit.set("state", "exporting")
                audit.db.commit()
                continue
            try:
                try:
                    target = audit.report("uploading")
                except Exception as intent_error:
                # Completion may have committed before its HTTP response was
                # lost. Reconcile that exact declaration instead of downgrading
                # a completed server row or uploading again indefinitely.
                    try:
                        audit.report("complete")
                    except Exception:
                        raise intent_error
                    reported.set()
                    audit.set("state", "complete")
                    audit.db.commit()
                    return
                reported.set()
                audit.upload(target.get("upload"), source)
            finally:
                source.close()
            audit.report("complete")
            audit.set("state", "complete")
            audit.db.commit()
            log("INFO", "space audit metadata report complete")
            return
        except Exception as exc:
            # Never log presigned URLs, request headers or authentication data.
            log("WARN", "space audit deferred (%s); checkpoint retained" % type(exc).__name__)
            if audit is not None:
                try:
                    audit.report_failure(exc)
                except Exception:
                    pass
        finally:
            if audit is not None:
                audit.close()
        stop_event.wait(60)


def mark_cleanup_verified_healthy(cfg, runtime, storage_checked, verified):
    # A fresh per-boot full NAS/R2 acknowledgement and authenticated heartbeat
    # can qualify this verifier even when the independent raw cursor feed fails.
    # Keep that feed's phase, error and progress unchanged.
    if (not storage_checked or not runtime.heartbeat_succeeded
            or not verified.is_set() or runtime.stable_marked):
        return False
    try:
        if cfg.is_candidate:
            promote_candidate(cfg)
        mark_runtime(cfg, runtime, "healthy")
    except Exception as exc:
        log("WARN", "cleanup verifier release stability mark deferred: %s" % exc)
        return False
    runtime.stable_marked = True
    return True


def mark_capacity_blocked_audit_healthy(cfg, runtime, storage_checked, audit_reported):
    # A full, correctly mounted NAS still needs audit updates. Promote only at
    # this main-thread safe boundary after two live authenticated API probes.
    if (not storage_checked or not runtime.is_capacity_blocked()
            or not runtime.heartbeat_succeeded or not audit_reported.is_set()
            or runtime.stable_marked):
        return False
    if cfg.is_candidate:
        promote_candidate(cfg)
    mark_runtime(cfg, runtime, "healthy")
    runtime.stable_marked = True
    return True


def run(cfg):
    CLIENT_LOG_RING.configure(cfg)
    cfg.validate()
    lock_handle = acquire_lock(cfg)
    _pins, pins_error = cleanup_pins()
    if pins_error is not None:
        # Deletion stays refused for this whole process; every other lane runs.
        log("ERROR", "NAS cleanup deletions disabled: %s" % pins_error)
    inventory = Inventory(cfg)
    runtime = Runtime(cfg, inventory)
    runtime.host_facts = HostFacts(cfg.state_dir)
    mark_runtime(cfg, runtime)
    stop_event = threading.Event()
    inventory_stop_event = threading.Event()
    joined_stop_event = threading.Event()
    update_ready = threading.Event()

    def stop(_signum, _frame):
        stop_event.set()
        inventory_stop_event.set()
        joined_stop_event.set()

    signal.signal(signal.SIGTERM, stop)
    signal.signal(signal.SIGINT, stop)
    heartbeat = threading.Thread(target=heartbeat_loop, args=(cfg, runtime, stop_event), daemon=True)
    heartbeat.start()
    threading.Thread(target=client_log_upload_loop, args=(cfg, runtime, inventory, stop_event), daemon=True).start()
    storage_probe = threading.Thread(target=storage_probe_loop, args=(cfg, runtime, stop_event), daemon=True)
    storage_probe.start()
    space_audit_reported = threading.Event()
    cleanup_verified = threading.Event()
    if not cfg.dry_run:
        threading.Thread(target=space_audit_loop, args=(cfg, stop_event, space_audit_reported), daemon=True).start()
    if not cfg.dry_run:
        # Daemon thread: an update or shutdown may cut a restore short; its
        # lease expires and the create-only PUT makes the retry safe.
        threading.Thread(target=restore_loop, args=(cfg, stop_event), daemon=True).start()
        # Verify-only selected manifests are independent from the cursor feed and
        # never write media bytes.
        threading.Thread(target=selected_verify_loop, args=(cfg, stop_event), daemon=True).start()
    cleanup_worker = None
    if not cfg.dry_run:
        cleanup_worker = threading.Thread(target=cleanup_loop, args=(cfg, inventory, inventory_stop_event, cleanup_verified), daemon=True)
        cleanup_worker.start()
    stitch_worker = None
    if getattr(cfg, "stitch_enabled", False) and not cfg.dry_run:
        stitch_worker = threading.Thread(target=stitch_loop, args=(cfg, inventory, inventory_stop_event), daemon=True, name="nas-v85r-stitch")
        stitch_worker.start()
    updater = threading.Thread(
        target=update_loop,
        args=(cfg, runtime, stop_event, inventory_stop_event, update_ready, joined_stop_event),
        daemon=True,
    )
    updater.start()
    inventory_worker = threading.Thread(
        target=inventory_loop, args=(cfg, inventory, inventory_stop_event), daemon=True,
    )
    inventory_worker.start()
    joined_worker = threading.Thread(
        target=joined_loop, args=(cfg, runtime, joined_stop_event), daemon=True,
    )
    joined_worker.start()
    if not cfg.dry_run:
        # Daemon thread: a self-update or shutdown may cut a probe short; the
        # API sweeps any unreported probe objects after their target expires.
        threading.Thread(target=upload_probe_loop, args=(cfg, runtime, stop_event), daemon=True).start()
    self_update_failed = False
    benchmark_worker = None
    if not cfg.dry_run:
        # Daemon thread: a staged self-update waits while BENCHMARK_ACTIVE is
        # set; shutdown kills the benchmark children via stop_event.
        benchmark_worker = threading.Thread(target=benchmark_loop, args=(cfg, runtime, stop_event), daemon=True)
        benchmark_worker.start()
    try:
        while not stop_event.is_set():
            # No delivery page is active at this boundary. A staged candidate
            # may replace the process even when storage/list work is failing,
            # provided the inventory thread has reached its stop checkpoint.
            if update_can_exec(update_ready, inventory_worker, stop_event, joined_worker, cleanup_worker):
                runtime.set_phase(Phase.UPDATING)
                exec_candidate(cfg, runtime)
            if not heartbeat.is_alive():
                log("WARN", "heartbeat thread dead; restarting")
                heartbeat = threading.Thread(target=heartbeat_loop, args=(cfg, runtime, stop_event), daemon=True)
                heartbeat.start()
            if not joined_worker.is_alive() and not joined_stop_event.is_set():
                log("WARN", "joined delivery thread dead; restarting")
                joined_worker = threading.Thread(
                    target=joined_loop, args=(cfg, runtime, joined_stop_event), daemon=True,
                )
                joined_worker.start()
            storage_checked = False
            try:
                check_storage(cfg)
                storage_checked = True
                mark_cleanup_verified_healthy(cfg, runtime, storage_checked, cleanup_verified)
                require_storage_capacity(cfg, runtime)
            except (RuntimeError, OSError) as exc:
                try:
                    mark_capacity_blocked_audit_healthy(cfg, runtime, storage_checked, space_audit_reported)
                except (RuntimeError, OSError):
                    log("WARN", "capacity-blocked audit release stability mark deferred")
                runtime.set_phase(Phase.BLOCKED)
                log("ERROR", "storage blocked: %s" % exc)
                stop_event.wait(cfg.poll_interval_sec)
                continue
            try:
                progress = drain_page(cfg, runtime, inventory)
                if runtime.heartbeat_succeeded and runtime.list_succeeded and not runtime.stable_marked:
                    if cfg.is_candidate:
                        promote_candidate(cfg)
                    # Bootstrap v1 rolls back only runtime states "running" and
                    # "self_update". Once both control-plane probes pass, mark
                    # this release stable so an ordinary container restart does
                    # not resurrect the previous client indefinitely.
                    mark_runtime(cfg, runtime, "healthy")
                    runtime.stable_marked = True
                if update_can_exec(update_ready, inventory_worker, stop_event, joined_worker, cleanup_worker):
                    runtime.set_phase(Phase.UPDATING)
                    exec_candidate(cfg, runtime)
                set_idle_unless_capacity_blocked(runtime)
                if not progress and not stop_event.is_set():
                    try:
                        certified = maybe_run_native_stitch(cfg, runtime, inventory, stop_event)
                    except Exception as exc:
                        certified = False
                        log("WARN", "native stitch certification deferred: %s" % exc)
                    if not certified:
                        stop_event.wait(cfg.poll_interval_sec)
            except Exception as exc:
                if isinstance(exc, SelfUpdateExecError):
                    raise
                runtime.set_error(str(exc))
                log("ERROR", "drain failed: %s" % exc)
                stop_event.wait(ERROR_BACKOFF_SEC)
    except SelfUpdateExecError:
        self_update_failed = True
        raise
    finally:
        stop_event.set()
        inventory_stop_event.set()
        joined_stop_event.set()
        heartbeat.join(timeout=HEARTBEAT_TIMEOUT_SEC + 1)
        storage_probe.join(timeout=1)
        inventory_worker.join(timeout=INVENTORY_SHUTDOWN_TIMEOUT_SEC)
        joined_worker.join(timeout=HTTP_TIMEOUT_SEC + 1)
        if benchmark_worker is not None:
            # The watchdog kills benchmark children within a second of stop;
            # wait for its temp-output cleanup before the process exits.
            benchmark_worker.join(timeout=15)
        if stitch_worker is not None:
            stitch_worker.join(timeout=HTTP_TIMEOUT_SEC + 5)
        if cleanup_worker is not None:
            cleanup_worker.join(timeout=HTTP_TIMEOUT_SEC + 5)
        cleanup_stuck = cleanup_worker is not None and cleanup_worker.is_alive()
        stitch_stuck = stitch_worker is not None and stitch_worker.is_alive()
        joined_stuck = joined_worker.is_alive() or cleanup_stuck or stitch_stuck
        if joined_stuck:
            log("ERROR", "joined delivery worker did not stop; process must exit unclean")
            mark_runtime(cfg, runtime, PreviousExit.UNCLEAN_PROCESS.value)
        elif not self_update_failed:
            mark_runtime(cfg, runtime, PreviousExit.CLEAN.value)
        if inventory_worker.is_alive() or (stitch_worker is not None and stitch_worker.is_alive()):
            log("WARN", "inventory/stitch worker still running at shutdown; leaving database open")
        elif not joined_stuck:
            inventory.close()
        if not joined_stuck:
            lock_handle.close()
        else:
            raise RuntimeError("joined delivery worker did not stop")
    return 0


def check(cfg):
    cfg.validate()
    check_storage(cfg)
    page = request_json(cfg, "GET", "/account/clips?after_id=0&limit=1")
    if not isinstance(page.get("clips", []), list):
        raise RuntimeError("invalid clips response")
    print("NAS storage mounts and API access are healthy")
    return 0


def validate_certification_storage(cfg):
    try:
        output_root = cfg.output_dir.resolve(strict=True)
        state_root = cfg.state_dir.resolve(strict=True)
        inventory_path = cfg.inventory_file.resolve(strict=True)
        lock_path = cfg.lock_file.resolve(strict=True)
    except OSError as exc:
        raise MediaCertificationError("required NAS certification storage is unavailable") from exc
    if (
        not output_root.is_dir() or not state_root.is_dir()
        or not os.path.ismount(str(output_root)) or not os.path.ismount(str(state_root))
        or output_root == state_root
    ):
        raise MediaCertificationError("NAS certification requires distinct mounted storage roots")
    if inventory_path.parent != state_root or lock_path.parent != state_root:
        raise MediaCertificationError("NAS certification state paths escape the state mount")


def acquire_certification_lock(cfg):
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
    try:
        descriptor = os.open(str(cfg.lock_file), flags)
        fcntl.flock(descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except (OSError, BlockingIOError) as exc:
        try:
            os.close(descriptor)
        except UnboundLocalError:
            pass
        raise MediaCertificationError("the NAS pull client must be stopped before certification") from exc
    return descriptor


def open_certification_inventory(cfg):
    if not cfg.inventory_file.is_file():
        raise MediaCertificationError("the NAS inventory database is unavailable")
    uri = "file:%s?mode=ro" % urllib.parse.quote(str(cfg.inventory_file.resolve()), safe="/")
    try:
        database = sqlite3.connect(uri, uri=True)
        database.execute("PRAGMA query_only=ON")
        values = dict(database.execute("SELECT key,value FROM meta").fetchall())
    except sqlite3.Error as exc:
        try:
            database.close()
        except UnboundLocalError:
            pass
        raise MediaCertificationError("the NAS inventory database is unreadable") from exc
    generation = values.get("generation", "")
    started_at = values.get("scan_started_at", "")
    pass_started_at = values.get("scan_pass_started_at", "")
    completed_at = values.get("scan_completed_at", "")
    digest = str(values.get("digest", "")).lower()
    try:
        skipped = int(values.get("scan_rows_skipped", "0"))
    except (TypeError, ValueError) as exc:
        database.close()
        raise MediaCertificationError("the NAS inventory completion proof is invalid") from exc
    if not generation or not started_at or not pass_started_at or not completed_at:
        database.close()
        raise MediaCertificationError("a completed NAS inventory scan is required")
    try:
        started = parse_certification_timestamp(started_at, "inventory scan_started_at")
        pass_started = parse_certification_timestamp(pass_started_at, "inventory scan_pass_started_at")
        completed = parse_certification_timestamp(completed_at, "inventory scan_completed_at")
        certification_sha(digest, "inventory digest")
    except MediaCertificationError as exc:
        database.close()
        raise MediaCertificationError("the NAS inventory completion proof is invalid") from exc
    if started > completed or pass_started > completed:
        database.close()
        raise MediaCertificationError("the NAS inventory completion proof is invalid")
    if skipped != 0:
        database.close()
        raise MediaCertificationError("the completed NAS inventory contains skipped paths")
    return database, {
        "generation": generation, "scan_started_at": started_at,
        "scan_pass_started_at": pass_started_at, "scan_completed_at": completed_at, "digest": digest,
    }


def certification_integer(value, field, minimum=0):
    if type(value) is not int or value < minimum:
        raise MediaCertificationError("stitch sidecar %s is invalid" % field)
    return value


def certification_sha(value, field):
    digest = str(value or "").lower()
    if len(digest) != 64 or any(character not in "0123456789abcdef" for character in digest):
        raise MediaCertificationError("%s is invalid" % field)
    return digest


def collect_certification_candidates(cfg, database, inventory_generation, recording_id, window_start, window_end, frozen_clips=None):
    frozen_ids = None
    if frozen_clips is not None:
        if not isinstance(frozen_clips, list) or not frozen_clips or len(frozen_clips) > NATIVE_STITCH_MAX_CLIPS:
            raise MediaCertificationError("invalid frozen task manifest")
        frozen_ids = [certification_integer(item.get("clip_id"), "frozen clip_id", 1) for item in frozen_clips]
        if len(set(frozen_ids)) != len(frozen_ids):
            raise MediaCertificationError("duplicate frozen clip id")
    try:
        if frozen_ids is None:
            rows = database.execute(
                """SELECT clip_id,relative_path,size_bytes,sha256,verified_at,seen_generation,state
                   FROM files WHERE recording_id=? ORDER BY clip_id""", (recording_id,),
            ).fetchall()
        else:
            placeholders = ",".join("?" for _ in frozen_ids)
            rows = database.execute(
                """SELECT clip_id,relative_path,size_bytes,sha256,verified_at,seen_generation,state
                   FROM files WHERE recording_id=? AND clip_id IN (%s) ORDER BY clip_id""" % placeholders,
                (recording_id, *frozen_ids),
            ).fetchall()
            extras = database.execute(
                """SELECT count(*) FROM files WHERE recording_id=? AND state='present' AND seen_generation=?
                   AND clip_start_us>0 AND clip_end_us>0 AND clip_end_us>? AND clip_start_us<?
                   AND clip_id NOT IN (%s)""" % placeholders,
                (recording_id, inventory_generation,
                 certification_timestamp_microseconds(window_start.isoformat(), "window_start"),
                 certification_timestamp_microseconds(window_end.isoformat(), "window_end"),
                 *frozen_ids),
            ).fetchone()[0]
            if extras:
                raise MediaCertificationError("local inventory has extra media intersecting frozen window")
    except sqlite3.Error as exc:
        raise MediaCertificationError("the NAS inventory clip proof is unreadable") from exc
    candidates = []
    seen_clip_ids = set()
    seen_sequences = set()
    for clip_id, relative_path, expected_size, expected_sha, verified_at, seen_generation, state in rows:
        sidecar, sidecar_size_bytes, sidecar_sha = read_certification_sidecar(cfg.output_dir, relative_path)
        inventory_clip_id = certification_integer(clip_id, "inventory clip_id", 1)
        inventory_size = certification_integer(expected_size, "inventory size_bytes", 0)
        inventory_sha = certification_sha(expected_sha, "inventory sha256")
        sidecar_clip_id = certification_integer(sidecar.get("clip_id"), "clip_id", 1)
        sidecar_recording_id = certification_integer(sidecar.get("recording_id"), "recording_id", 1)
        sidecar_size = certification_integer(sidecar.get("size_bytes"), "size_bytes", 0)
        sidecar_digest = certification_sha(sidecar.get("sha256"), "stitch sidecar sha256")
        if (
            sidecar.get("schema_version") != 1 or sidecar_clip_id != inventory_clip_id
            or sidecar_recording_id != recording_id
            or str(sidecar.get("relative_path", "")) != relative_path
            or sidecar_size != inventory_size or sidecar_digest != inventory_sha
        ):
            raise MediaCertificationError("stitch sidecar does not match inventory metadata")
        clip_start = parse_certification_timestamp(sidecar.get("clip_start_at"), "clip_start_at")
        clip_end = parse_certification_timestamp(sidecar.get("clip_end_at"), "clip_end_at")
        if clip_end <= clip_start:
            raise MediaCertificationError("clip timeline is invalid")
        if clip_end <= window_start or clip_start >= window_end:
            continue
        if state != "present":
            raise MediaCertificationError("requested window contains media without exact NAS proof")
        if str(seen_generation) != inventory_generation:
            raise MediaCertificationError("clip proof is not from the completed inventory generation")
        verified_timestamp = parse_certification_timestamp(verified_at, "inventory verified_at")
        capture_generation = str(sidecar.get("capture_generation") or "").strip()
        sequence = certification_integer(sidecar.get("capture_sequence"), "capture_sequence", 0)
        job_id = certification_integer(sidecar.get("recording_job_id"), "recording_job_id", 1)
        # Capture provenance is tri-state during rolling deployment: historical
        # NULL, probe UNKNOWN, or COMPLETE with an exact contract.
        capture_attempt_id = str(sidecar.get("capture_attempt_id") or "")
        timestamp_version = str(sidecar.get("timestamp_contract_version") or "")
        timestamp_status = str(sidecar.get("timestamp_contract_status") or "")
        timestamp_reason = str(sidecar.get("timestamp_contract_reason") or "")
        timestamp_contract = sidecar.get("timestamp_contract")
        timestamp_contract_sha = timestamp_contract_hash(timestamp_contract) if isinstance(timestamp_contract, dict) else ""
        complete_timestamp = capture_attempt_id and timestamp_status == "per_clip_probe_complete" and timestamp_version == "continuous-source-pts-v1" and timestamp_reason == "" and isinstance(timestamp_contract, dict)
        unknown_timestamp = capture_attempt_id and timestamp_status == "per_clip_probe_unknown" and not timestamp_version and timestamp_reason in ("missing_terminal_duration","missing_audio_sample_count","invalid_time_base","probe_output_limit","probe_unavailable") and timestamp_contract is None
        legacy_timestamp = not capture_attempt_id and not timestamp_version and not timestamp_status and not timestamp_reason and timestamp_contract is None
        if not (complete_timestamp or unknown_timestamp or legacy_timestamp):
            raise MediaCertificationError("clip timestamp provenance is incoherent")
        if not capture_generation or len(capture_generation) > 256 or any(ord(character) < 32 for character in capture_generation):
            raise MediaCertificationError("clip lacks canonical stitch provenance")
        if inventory_clip_id in seen_clip_ids or (job_id, capture_generation, sequence) in seen_sequences:
            raise MediaCertificationError("duplicate stitch provenance")
        seen_clip_ids.add(inventory_clip_id)
        seen_sequences.add((job_id, capture_generation, sequence))
        candidates.append({
            "clip_id": inventory_clip_id, "recording_id": sidecar_recording_id, "recording_job_id": job_id,
            "relative_path": relative_path, "size_bytes": inventory_size,
            "sha256": inventory_sha,
            "inventory_verified_at": verified_timestamp.isoformat().replace("+00:00", "Z"),
            "sidecar_size_bytes": sidecar_size_bytes, "sidecar_sha256": sidecar_sha,
            "capture_generation": capture_generation, "capture_sequence": sequence,
            "capture_attempt_id": capture_attempt_id,
            "timestamp_contract_version": timestamp_version,
            "timestamp_contract_status": timestamp_status,
            "timestamp_contract_reason": timestamp_reason,
            "timestamp_contract_sha256": timestamp_contract_sha,
            "timestamp_contract": timestamp_contract,
            "clip_start_at": clip_start, "clip_end_at": clip_end,
        })
    candidates.sort(key=lambda item: (
        item["clip_start_at"], item["capture_generation"], item["capture_sequence"], item["clip_id"],
    ))
    if frozen_ids is not None and {item["clip_id"] for item in candidates} != set(frozen_ids):
        raise MediaCertificationError("local inventory does not equal frozen manifest")
    if len({item["recording_job_id"] for item in candidates}) > 1:
        raise MediaCertificationError("requested window contains multiple recording jobs")
    sequence_groups = {}
    for item in candidates:
        key = (item["recording_job_id"], item["capture_generation"])
        sequence_groups.setdefault(key, []).append(item["capture_sequence"])
    for sequences in sequence_groups.values():
        ordered = sorted(sequences)
        if ordered != list(range(ordered[0], ordered[-1] + 1)):
            raise MediaCertificationError("selected capture sequence is incomplete")
    for previous, current in zip(candidates, candidates[1:]):
        if current["clip_start_at"] < previous["clip_end_at"]:
            raise MediaCertificationError("selected clips overlap")
    return candidates


def certify_media_canary(cfg, recording_id, window_start_raw, window_end_raw, limit, ffmpeg_bin, ffprobe_bin):
    if recording_id <= 0:
        raise MediaCertificationError("recording id must be positive")
    if limit < 1 or limit > MEDIA_CERTIFICATION_MAX_CLIPS:
        raise MediaCertificationError("limit must be between 1 and %d" % MEDIA_CERTIFICATION_MAX_CLIPS)
    window_start = parse_certification_timestamp(window_start_raw, "window_start")
    window_end = parse_certification_timestamp(window_end_raw, "window_end")
    if window_end <= window_start:
        raise MediaCertificationError("window_end must be after window_start")
    validate_certification_storage(cfg)
    lock_descriptor = acquire_certification_lock(cfg)
    try:
        return certify_media_canary_locked(
            cfg, recording_id, window_start, window_end, limit, ffmpeg_bin, ffprobe_bin,
        )
    finally:
        fcntl.flock(lock_descriptor, fcntl.LOCK_UN)
        os.close(lock_descriptor)


def certify_media_canary_locked(cfg, recording_id, window_start, window_end, limit, ffmpeg_bin, ffprobe_bin):
    inventory, summary = open_certification_inventory(cfg)
    try:
        all_candidates = collect_certification_candidates(
            cfg, inventory, summary["generation"], recording_id, window_start, window_end,
        )
    finally:
        inventory.close()
    if not all_candidates:
        raise MediaCertificationError("no inventory clips intersect the requested window")
    selected = all_candidates[:limit]
    selected_bytes = sum(item["size_bytes"] for item in selected)
    if selected_bytes > MEDIA_CERTIFICATION_MAX_BYTES:
        raise MediaCertificationError("selected media exceeds the canary byte budget")
    filesystem = os.statvfs(str(cfg.state_dir))
    free_bytes = filesystem.f_bavail * filesystem.f_frsize
    if free_bytes < selected_bytes * 2 + MEDIA_CERTIFICATION_TEMP_RESERVE_BYTES:
        raise MediaCertificationError("insufficient temporary capacity for lossless validation")
    tool_versions = {
        "ffmpeg": media_tool_version(ffmpeg_bin),
        "ffprobe": media_tool_version(ffprobe_bin),
    }
    clip_reports = []
    selected_paths = []
    selected_identities = []
    for item in selected:
        path, file_stat, actual_sha = hash_certification_file(
            cfg.output_dir, item["relative_path"], item["size_bytes"], item["sha256"],
        )
        probe = probe_native_media(path, ffprobe_bin)
        expected_duration = (item["clip_end_at"] - item["clip_start_at"]).total_seconds()
        if abs(probe["duration_seconds"] - expected_duration) > MEDIA_CERTIFICATION_DURATION_TOLERANCE_SEC:
            raise MediaCertificationError("container duration does not match the clip timeline")
        strict_decode_media(path, ffmpeg_bin)
        # The decode is a second full read. Recheck the pathname identity so a
        # replacement during verification cannot inherit the earlier hash proof.
        after_decode = path.stat()
        if certification_identity(file_stat) != certification_identity(after_decode):
            raise MediaCertificationError("media identity changed during decode")
        signature_sha = canonical_report_hash(probe["signature"])
        clip_reports.append({
            "clip_id": item["clip_id"], "recording_job_id": item["recording_job_id"],
            "relative_path": item["relative_path"], "size_bytes": item["size_bytes"],
            "sha256": actual_sha, "capture_generation": item["capture_generation"],
            "capture_sequence": item["capture_sequence"],
            "clip_start_at": item["clip_start_at"].isoformat().replace("+00:00", "Z"),
            "clip_end_at": item["clip_end_at"].isoformat().replace("+00:00", "Z"),
            "inventory_verified_at": item["inventory_verified_at"],
            "sidecar_size_bytes": item["sidecar_size_bytes"],
            "sidecar_sha256": item["sidecar_sha256"],
            "file_identity": {
                "size": after_decode.st_size, "mtime_ns": after_decode.st_mtime_ns,
                "ctime_ns": after_decode.st_ctime_ns, "inode": after_decode.st_ino,
                "device": after_decode.st_dev,
            },
            "probe": probe, "native_signature_sha256": signature_sha,
            "strict_decode": "passed",
        })
        selected_paths.append(path)
        selected_identities.append(certification_identity(after_decode))
    runs = []
    run_start = 0
    with tempfile.TemporaryDirectory(prefix="stoarama-certify-", dir=str(cfg.state_dir)) as raw_temp:
        temp_root = Path(raw_temp)
        for index in range(1, len(clip_reports) + 1):
            boundary = index == len(clip_reports)
            if not boundary:
                current_key = (
                    clip_reports[index]["recording_job_id"], clip_reports[index]["capture_generation"],
                    clip_reports[index]["native_signature_sha256"],
                )
                run_key = (
                    clip_reports[run_start]["recording_job_id"], clip_reports[run_start]["capture_generation"],
                    clip_reports[run_start]["native_signature_sha256"],
                )
                boundary = current_key != run_key
            if not boundary:
                continue
            run_paths = selected_paths[run_start:index]
            run_dir = temp_root / ("run-%d" % len(runs))
            run_dir.mkdir()
            concat_state = validate_native_run(run_paths, ffmpeg_bin, run_dir)
            runs.append({
                "first_clip_id": clip_reports[run_start]["clip_id"],
                "last_clip_id": clip_reports[index - 1]["clip_id"],
                "clip_count": index - run_start,
                "native_signature_sha256": clip_reports[run_start]["native_signature_sha256"],
                "lossless_stitch_validation": concat_state,
            })
            run_start = index
    for path, expected_identity in zip(selected_paths, selected_identities):
        if certification_identity(path.stat()) != expected_identity:
            raise MediaCertificationError("media identity changed during stitch validation")
    final_inventory, final_summary = open_certification_inventory(cfg)
    final_inventory.close()
    if final_summary != summary:
        raise MediaCertificationError("NAS inventory completion changed during certification")
    internal_gaps = [
        max(0.0, (current["clip_start_at"] - previous["clip_end_at"]).total_seconds())
        for previous, current in zip(selected, selected[1:])
    ]
    report = {
        "schema_version": MEDIA_CERTIFICATION_SCHEMA_VERSION,
        "certification_scope": "bounded_clip_canary",
        "window_complete": False,
        "recording_id": recording_id,
        "window_start_at": window_start.isoformat().replace("+00:00", "Z"),
        "window_end_at": window_end.isoformat().replace("+00:00", "Z"),
        "inventory_generation": summary.get("generation", ""),
        "inventory_digest": summary.get("digest", ""),
        "inventory_scan_started_at": summary.get("scan_started_at"),
        "inventory_scan_pass_started_at": summary.get("scan_pass_started_at"),
        "inventory_completed_at": summary.get("scan_completed_at"),
        "available_window_clip_count": len(all_candidates),
        "selected_clip_count": len(selected),
        "selected_bytes": selected_bytes,
        "selected_internal_gap_count": sum(1 for gap in internal_gaps if gap > 0),
        "selected_largest_internal_gap_seconds": max(internal_gaps, default=0.0),
        "selected_overlap_count": 0,
        "truncated_by_canary_limit": len(selected) < len(all_candidates),
        "clips": clip_reports,
        "native_runs": runs,
        "tools": tool_versions,
        "source_media_modified": False,
        "reencoded": False,
        "persistent_output_created": False,
        "created_at": datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z"),
    }
    report["report_sha256"] = canonical_report_hash(report)
    return report


def main(argv=None):
    parser = argparse.ArgumentParser(description="Stoarama NAS pull client")
    parser.add_argument("command", nargs="?", choices=("run", "check", "version", "self-update", "certify"), default="run")
    parser.add_argument("--recording-id", type=int, default=0)
    parser.add_argument("--window-start", default="")
    parser.add_argument("--window-end", default="")
    parser.add_argument("--limit", type=int, default=2)
    parser.add_argument("--ffmpeg-bin", default=os.environ.get("FFMPEG_BIN", "ffmpeg"))
    parser.add_argument("--ffprobe-bin", default=os.environ.get("FFPROBE_BIN", "ffprobe"))
    args = parser.parse_args(argv)
    if args.command == "version":
        print(CLIENT_VERSION)
        return 0
    cfg = Config()
    if args.command == "check":
        return check(cfg)
    if args.command == "self-update":
        cfg.validate()
        print(stage_update(cfg) or "already-current")
        return 0
    if args.command == "certify":
        try:
            report = certify_media_canary(
                cfg, args.recording_id, args.window_start, args.window_end,
                args.limit, args.ffmpeg_bin, args.ffprobe_bin,
            )
        except MediaCertificationError as exc:
            print("certification failed: %s" % exc, file=sys.stderr)
            return 1
        except Exception:
            print("certification failed: unexpected local verification failure", file=sys.stderr)
            return 1
        print(json.dumps(report, sort_keys=True, separators=(",", ":")))
        return 0
    return run(cfg)


if __name__ == "__main__":
    sys.exit(main())
